window.READING_REVIEW_DATA = {"items":[{"id":"maple-429d1d9f6d","term":"maple","type":"word","sourceOrder":1,"zh":"枫树","pos":"n.","ipa":"ˈmeɪpəl","stars":2,"note":"maple leaf 枫叶；maple syrup 枫糖浆","paragraph":"听力原文","examples":[{"en":"You will hear a lecture on a very popular Canadian food product called maple syrup.","zh":"你将听到一场有关加拿大广受欢迎的食品——枫糖浆的讲座。","source":"original","number":2},{"en":"Maple syrup can be described as very sweet.","zh":"枫糖浆可以被形容为非常甜。","source":"original","number":5},{"en":"The syrup is produced from the maple tree, and it actually comes from the tree's sap, which is the watery substance that comes out of the trunk of the tree when this is cut.","zh":"这种糖浆产自枫树，实际来源于枫树的树液；树液是一种含水物质，当树干被切开时会从中流出。","source":"original","number":7}]},{"id":"maple-cf45a34ab8","term":"syrup","type":"word","sourceOrder":2,"zh":"糖浆","pos":"n.","ipa":"ˈsɪrəp","stars":3,"note":"cough syrup 止咳糖浆；corn syrup 玉米糖浆","paragraph":"听力原文","examples":[{"en":"You will hear a lecture on a very popular Canadian food product called maple syrup.","zh":"你将听到一场有关加拿大广受欢迎的食品——枫糖浆的讲座。","source":"original","number":2},{"en":"Maple syrup can be described as very sweet.","zh":"枫糖浆可以被形容为非常甜。","source":"original","number":5},{"en":"The syrup is produced from the maple tree, and it actually comes from the tree's sap, which is the watery substance that comes out of the trunk of the tree when this is cut.","zh":"这种糖浆产自枫树，实际来源于枫树的树液；树液是一种含水物质，当树干被切开时会从中流出。","source":"original","number":7}]},{"id":"maple-b796b495dd","term":"generously","type":"word","sourceOrder":3,"zh":"大量地（浇糖浆）","pos":"adv.","ipa":"ˈdʒenərəsli","stars":3,"note":"慷慨地；generous=丰厚的/充足的","paragraph":"听力原文","examples":[{"en":"Canadians pour it generously over things like pancakes for breakfast.","zh":"加拿大人早餐时常把它大量浇在煎饼等食物上。","source":"original","number":6}]},{"id":"maple-69c2c3b401","term":"pour","type":"word","sourceOrder":4,"zh":"倾倒、浇在……上","pos":"v.","ipa":"pɔː","stars":2,"note":"pour into 大量涌入；pour with rain 下倾盆大雨","paragraph":"听力原文","examples":[{"en":"Canadians pour it generously over things like pancakes for breakfast.","zh":"加拿大人早餐时常把它大量浇在煎饼等食物上。","source":"original","number":6}]},{"id":"maple-0ceafb240b","term":"sap","type":"word","sourceOrder":5,"zh":"树液","pos":"n.","ipa":"sæp","stars":2,"note":"v. 消耗/削弱（sap energy）；n. （非正式）傻瓜","paragraph":"听力原文","examples":[{"en":"The syrup is produced from the maple tree, and it actually comes from the tree's sap, which is the watery substance that comes out of the trunk of the tree when this is cut.","zh":"这种糖浆产自枫树，实际来源于枫树的树液；树液是一种含水物质，当树干被切开时会从中流出。","source":"original","number":7},{"en":"In order for enough sap to be produced, very special climate conditions are needed.","zh":"为了产生足够的树液，需要非常特殊的气候条件。","source":"original","number":8},{"en":"Clear sap started to run from the cut.","zh":"清澈的树液开始从切口处流出来。","source":"original","number":13}]},{"id":"maple-d6ef3b6160","term":"watery","type":"word","sourceOrder":6,"zh":"水分多的、稀的","pos":"adj.","ipa":"ˈwɔːtəri","stars":3,"note":"watery eyes 眼睛含泪；watery soup 稀汤","paragraph":"听力原文","examples":[{"en":"The syrup is produced from the maple tree, and it actually comes from the tree's sap, which is the watery substance that comes out of the trunk of the tree when this is cut.","zh":"这种糖浆产自枫树，实际来源于枫树的树液；树液是一种含水物质，当树干被切开时会从中流出。","source":"original","number":7}]},{"id":"maple-31343ead24","term":"substance","type":"word","sourceOrder":7,"zh":"物质","pos":"n.","ipa":"ˈsʌbstəns","stars":3,"note":"物质/实质：the substance of an argument 论点核心","paragraph":"听力原文","examples":[{"en":"The syrup is produced from the maple tree, and it actually comes from the tree's sap, which is the watery substance that comes out of the trunk of the tree when this is cut.","zh":"这种糖浆产自枫树，实际来源于枫树的树液；树液是一种含水物质，当树干被切开时会从中流出。","source":"original","number":7}]},{"id":"maple-69d5aa7fb3","term":"trunk","type":"word","sourceOrder":8,"zh":"树干","pos":"n.","ipa":"trʌŋk","stars":2,"note":"汽车后备箱（美式）；象鼻；大旅行箱","paragraph":"听力原文","examples":[{"en":"The syrup is produced from the maple tree, and it actually comes from the tree's sap, which is the watery substance that comes out of the trunk of the tree when this is cut.","zh":"这种糖浆产自枫树，实际来源于枫树的树液；树液是一种含水物质，当树干被切开时会从中流出。","source":"original","number":7},{"en":"Early folk stories say it was first discovered by a chief who threw his tomahawk, which is similar to an ax, into the trunk of a tree.","zh":"早期民间故事称，一位酋长把战斧掷入树干，从而首先发现了枫树液；战斧类似斧头。","source":"original","number":12}]},{"id":"maple-30090c0ed5","term":"climate","type":"word","sourceOrder":9,"zh":"气候","pos":"n.","ipa":"ˈklaɪmət","stars":3,"note":"economic/political climate 经济/政治环境（引申义）","paragraph":"听力原文","examples":[{"en":"In order for enough sap to be produced, very special climate conditions are needed.","zh":"为了产生足够的树液，需要非常特殊的气候条件。","source":"original","number":8},{"en":"It is predicted with some certainty that in the longer term, climate change will also have an adverse effect on the sap run.","zh":"可以比较肯定地预测，从长远看，气候变化也会对树液流动产生不利影响。","source":"original","number":45}]},{"id":"maple-15ae012c2c","term":"condition","type":"word","sourceOrder":10,"zh":"条件（气候条件）","pos":"n.","ipa":"kənˈdɪʃən","stars":3,"note":"情况/健康状况；on condition that 条件是","paragraph":"听力原文","examples":[{"en":"In order for enough sap to be produced, very special climate conditions are needed.","zh":"为了产生足够的树液，需要非常特殊的气候条件。","source":"original","number":8}]},{"id":"maple-0c88693c66","term":"temperature","type":"word","sourceOrder":11,"zh":"温度","pos":"n.","ipa":"ˈtemprətʃə","stars":3,"note":"body temperature 体温；通常考拼写","paragraph":"听力原文","examples":[{"en":"In spring, the temperatures need to drop to well below zero at night, but then they need to rise sharply during the day, so they're hugely different over a twenty-four-hour period.","zh":"春季夜间温度需要降到远低于零度，白天又要急剧升高，因此24小时内昼夜温度差异很大。","source":"original","number":9},{"en":"Another method that they used to concentrate the syrup was to leave the sap outside overnight, exposed to freezing temperatures.","zh":"另一种浓缩方法是把树液放在户外过夜，使其暴露在冰冻温度下。","source":"original","number":23}]},{"id":"maple-e476fabff9","term":"sharply","type":"word","sourceOrder":12,"zh":"急剧地（上升）","pos":"adv.","ipa":"ˈʃɑːpli","stars":3,"note":"尖锐地；严厉地；sharp 还可指聪明的","paragraph":"听力原文","examples":[{"en":"In spring, the temperatures need to drop to well below zero at night, but then they need to rise sharply during the day, so they're hugely different over a twenty-four-hour period.","zh":"春季夜间温度需要降到远低于零度，白天又要急剧升高，因此24小时内昼夜温度差异很大。","source":"original","number":9}]},{"id":"maple-d9a24eede4","term":"hugely","type":"word","sourceOrder":13,"zh":"极其、非常","pos":"adv.","ipa":"ˈhjuːdʒli","stars":3,"note":"hugely successful 非常成功","paragraph":"听力原文","examples":[{"en":"In spring, the temperatures need to drop to well below zero at night, but then they need to rise sharply during the day, so they're hugely different over a twenty-four-hour period.","zh":"春季夜间温度需要降到远低于零度，白天又要急剧升高，因此24小时内昼夜温度差异很大。","source":"original","number":9}]},{"id":"maple-e10936f786","term":"indigenous","type":"word","sourceOrder":14,"zh":"原住民的、本土的","pos":"adj.","ipa":"ɪnˈdɪdʒɪnəs","stars":5,"note":"indigenous species 本地物种；常与 native 对应","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"整体记 indigenous；与 native 联记","tip":"原住民或本土物种都可用；注意不是 endangered 濒危的。","family":"indigenous peoples 原住民；native 本土的"},"examples":[{"en":"The indigenous peoples of North America, known as the First Nations, discovered the maple's secret long before the Europeans arrived.","zh":"北美原住民（称为 First Nations，即“第一民族”）早在欧洲人到来很久之前就发现了枫树的秘密。","source":"original","number":11}]},{"id":"maple-d805c23734","term":"folk","type":"word","sourceOrder":15,"zh":"民间的","pos":"adj./n.","ipa":"fəʊk","stars":3,"note":"folk music 民间音乐；folks 人们（口语）","paragraph":"听力原文","examples":[{"en":"Early folk stories say it was first discovered by a chief who threw his tomahawk, which is similar to an ax, into the trunk of a tree.","zh":"早期民间故事称，一位酋长把战斧掷入树干，从而首先发现了枫树液；战斧类似斧头。","source":"original","number":12}]},{"id":"maple-f052d32f09","term":"chief","type":"word","sourceOrder":16,"zh":"酋长","pos":"n./adj.","ipa":"tʃiːf","stars":3,"note":"主要的；chief cause 主要原因","paragraph":"听力原文","examples":[{"en":"Early folk stories say it was first discovered by a chief who threw his tomahawk, which is similar to an ax, into the trunk of a tree.","zh":"早期民间故事称，一位酋长把战斧掷入树干，从而首先发现了枫树液；战斧类似斧头。","source":"original","number":12}]},{"id":"maple-56a7dcc474","term":"tomahawk","type":"word","sourceOrder":17,"zh":"（原住民的）战斧","pos":"n.","ipa":"ˈtɒməhɔːk","stars":5,"note":"语境专有词；即便不认识可借 similar to an ax 理解","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"整体记忆；借原文解释 similar to an ax 理解","tip":"遇到专门名词，利用后面的斧头 ax 释义理解，不必凭字母乱拆。","family":"ax / axe 斧头；a tomahawk 战斧"},"examples":[{"en":"Early folk stories say it was first discovered by a chief who threw his tomahawk, which is similar to an ax, into the trunk of a tree.","zh":"早期民间故事称，一位酋长把战斧掷入树干，从而首先发现了枫树液；战斧类似斧头。","source":"original","number":12}]},{"id":"maple-49cd67ba57","term":"ax / axe","type":"phrase","sourceOrder":18,"zh":"斧头","pos":"n.","ipa":"æks","stars":3,"note":"axe 为常见英式拼写；axe a plan 取消计划","paragraph":"听力原文","examples":[{"en":"Early folk stories say it was first discovered by a chief who threw his tomahawk, which is similar to an ax, into the trunk of a tree.","zh":"早期民间故事称，一位酋长把战斧掷入树干，从而首先发现了枫树液；战斧类似斧头。","source":"original","number":12}]},{"id":"maple-c8ce8fb2e7","term":"run","type":"word","sourceOrder":19,"zh":"（树液）流出；树液流动","pos":"v./n.","ipa":"rʌn","stars":3,"note":"经营公司/运行程序/跑步；sap run 树液流动期","paragraph":"听力原文","examples":[{"en":"Clear sap started to run from the cut.","zh":"清澈的树液开始从切口处流出来。","source":"original","number":13},{"en":"It is predicted with some certainty that in the longer term, climate change will also have an adverse effect on the sap run.","zh":"可以比较肯定地预测，从长远看，气候变化也会对树液流动产生不利影响。","source":"original","number":45}]},{"id":"maple-9e264f36e8","term":"cut","type":"word","sourceOrder":20,"zh":"切口","pos":"n./v.","ipa":"kʌt","stars":1,"note":"削减（cost cuts）；删减；砍/切（动词）","paragraph":"听力原文","examples":[{"en":"The syrup is produced from the maple tree, and it actually comes from the tree's sap, which is the watery substance that comes out of the trunk of the tree when this is cut.","zh":"这种糖浆产自枫树，实际来源于枫树的树液；树液是一种含水物质，当树干被切开时会从中流出。","source":"original","number":7},{"en":"Clear sap started to run from the cut.","zh":"清澈的树液开始从切口处流出来。","source":"original","number":13}]},{"id":"maple-5a63cf51d3","term":"boil","type":"word","sourceOrder":21,"zh":"煮沸","pos":"v.","ipa":"bɔɪl","stars":2,"note":"boil down to 归结为；boiling point 沸点","paragraph":"听力原文","examples":[{"en":"His wife used this sap to boil meat, and the heat turned it into a sweet syrup, which they found delicious.","zh":"他的妻子用这树液煮肉，热量使它变成甜糖浆，他们觉得味道很好。","source":"original","number":14}]},{"id":"maple-4bcc29a0ec","term":"tradition","type":"word","sourceOrder":22,"zh":"传统","pos":"n.","ipa":"trəˈdɪʃən","stars":3,"note":"cultural tradition 文化传统；traditional adj.","paragraph":"听力原文","examples":[{"en":"Collecting the sap each spring became a tradition among them.","zh":"每年春天采集树液逐渐成为他们的一项传统。","source":"original","number":16}]},{"id":"maple-ade18cd377","term":"migrate","type":"word","sourceOrder":23,"zh":"迁徙、迁移","pos":"v.","ipa":"maɪˈɡreɪt","stars":3,"note":"移居；animal migration 动物迁徙","paragraph":"听力原文","examples":[{"en":"Whole families would migrate to the areas where the maple trees grew and set up camp there.","zh":"整个家族过去常常迁往枫树生长的地区，并在那里扎营。","source":"original","number":17}]},{"id":"maple-affb063127","term":"camp","type":"word","sourceOrder":24,"zh":"营地；扎营","pos":"n./v.","ipa":"kæmp","stars":2,"note":"campaign 不是 camp 的同义词；camp out 露营","paragraph":"听力原文","examples":[{"en":"Whole families would migrate to the areas where the maple trees grew and set up camp there.","zh":"整个家族过去常常迁往枫树生长的地区，并在那里扎营。","source":"original","number":17}]},{"id":"maple-bf193b8820","term":"bucket","type":"word","sourceOrder":25,"zh":"桶","pos":"n.","ipa":"ˈbʌkɪt","stars":2,"note":"bucket list 人生愿望清单（非本句义）","paragraph":"听力原文","examples":[{"en":"They collected the sap from the trees using buckets.","zh":"他们用桶从枫树上采集树液。","source":"original","number":18},{"en":"One way was to drop hot stones from a fire into the buckets to create steam.","zh":"其中一种办法是把从火里取出的热石头放进桶里，从而产生蒸汽。","source":"original","number":21}]},{"id":"maple-2a3949164e","term":"concentrate","type":"word","sourceOrder":26,"zh":"浓缩树液（去水分）","pos":"v.","ipa":"ˈkɒnsəntreɪt","stars":4,"note":"集中注意力于；concentrated juice 浓缩果汁","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"concentrate → concentration；同一词可指集中或浓缩","tip":"树液去掉水分后浓度更高；本文不是集中注意力。","family":"concentration 浓度／专注；concentrated 浓缩的"},"examples":[{"en":"Then they needed to concentrate the sap, removing some of the water from it to create syrup.","zh":"接着他们需要浓缩树液，去除部分水分以制成糖浆。","source":"original","number":19},{"en":"If repeated often enough, this would eventually concentrate the syrup.","zh":"如果重复足够多次，最终就能把糖浆浓缩。","source":"original","number":22},{"en":"Another method that they used to concentrate the syrup was to leave the sap outside overnight, exposed to freezing temperatures.","zh":"另一种浓缩方法是把树液放在户外过夜，使其暴露在冰冻温度下。","source":"original","number":23}]},{"id":"maple-70177d7b01","term":"steam","type":"word","sourceOrder":27,"zh":"蒸汽","pos":"n.","ipa":"stiːm","stars":2,"note":"v. 蒸（食物）；let off steam 发泄压力；易错拼 steem","paragraph":"听力原文","examples":[{"en":"One way was to drop hot stones from a fire into the buckets to create steam.","zh":"其中一种办法是把从火里取出的热石头放进桶里，从而产生蒸汽。","source":"original","number":21}]},{"id":"maple-469965a948","term":"eventually","type":"word","sourceOrder":28,"zh":"最终","pos":"adv.","ipa":"ɪˈventʃuəli","stars":3,"note":"= in the end；不等于 possibly（可能）","paragraph":"听力原文","examples":[{"en":"If repeated often enough, this would eventually concentrate the syrup.","zh":"如果重复足够多次，最终就能把糖浆浓缩。","source":"original","number":22},{"en":"Again, this process could be repeated over several days, and eventually a sweet brown syrup was produced.","zh":"同样，这个过程可持续数天，最终得到棕色的甜糖浆。","source":"original","number":25}]},{"id":"maple-b567740b60","term":"overnight","type":"word","sourceOrder":29,"zh":"过夜","pos":"adv./adj.","ipa":"ˌəʊvəˈnaɪt","stars":3,"note":"突然间：an overnight success 一夜成名","paragraph":"听力原文","examples":[{"en":"Another method that they used to concentrate the syrup was to leave the sap outside overnight, exposed to freezing temperatures.","zh":"另一种浓缩方法是把树液放在户外过夜，使其暴露在冰冻温度下。","source":"original","number":23}]},{"id":"maple-22d13419e1","term":"expose","type":"word","sourceOrder":30,"zh":"暴露（于低温）","pos":"v.","ipa":"ɪkˈspəʊz","stars":3,"note":"揭露；be exposed to 噪声/风险/疾病","paragraph":"听力原文","examples":[{"en":"Another method that they used to concentrate the syrup was to leave the sap outside overnight, exposed to freezing temperatures.","zh":"另一种浓缩方法是把树液放在户外过夜，使其暴露在冰冻温度下。","source":"original","number":23}]},{"id":"maple-959812ed1d","term":"freezing","type":"word","sourceOrder":31,"zh":"冰冻的、极冷的","pos":"adj.","ipa":"ˈfriːzɪŋ","stars":3,"note":"freezing point 冰点；I’m freezing 冻死了","paragraph":"听力原文","examples":[{"en":"Another method that they used to concentrate the syrup was to leave the sap outside overnight, exposed to freezing temperatures.","zh":"另一种浓缩方法是把树液放在户外过夜，使其暴露在冰冻温度下。","source":"original","number":23}]},{"id":"maple-bd2efe9782","term":"layer","type":"word","sourceOrder":32,"zh":"一层（冰）","pos":"n.","ipa":"ˈleɪə","stars":2,"note":"a layer of paint 一层漆；layered adj. 分层的","paragraph":"听力原文","examples":[{"en":"This would mean that a thick layer of ice would form on top, which could be discarded, leaving the sugary sap below.","zh":"这样顶部会结出一层厚冰；冰层可以被丢弃，下面的含糖树液则保留下来。","source":"original","number":24}]},{"id":"maple-4eb0c7d2ad","term":"discard","type":"word","sourceOrder":33,"zh":"丢弃、去除","pos":"v.","ipa":"dɪˈskɑːd","stars":3,"note":"discard outdated ideas 抛弃旧观念","paragraph":"听力原文","examples":[{"en":"This would mean that a thick layer of ice would form on top, which could be discarded, leaving the sugary sap below.","zh":"这样顶部会结出一层厚冰；冰层可以被丢弃，下面的含糖树液则保留下来。","source":"original","number":24}]},{"id":"maple-908daf999e","term":"sugary","type":"word","sourceOrder":34,"zh":"含糖的","pos":"adj.","ipa":"ˈʃʊɡəri","stars":3,"note":"甜腻的；过分甜言蜜语的（引申）","paragraph":"听力原文","examples":[{"en":"This would mean that a thick layer of ice would form on top, which could be discarded, leaving the sugary sap below.","zh":"这样顶部会结出一层厚冰；冰层可以被丢弃，下面的含糖树液则保留下来。","source":"original","number":24}]},{"id":"maple-548f536e0e","term":"various","type":"word","sourceOrder":35,"zh":"各种不同的","pos":"adj.","ipa":"ˈveəriəs","stars":3,"note":"= a range of；variety n. 多样性","paragraph":"听力原文","examples":[{"en":"The First Nations people had various uses for the sap and syrup.","zh":"第一民族对树液和糖浆有多种用途。","source":"original","number":26}]},{"id":"maple-3f2a4100fb","term":"tonic","type":"word","sourceOrder":36,"zh":"滋补饮品","pos":"n.","ipa":"ˈtɒnɪk","stars":3,"note":"补剂；使人振作的事物（a tonic）","paragraph":"听力原文","examples":[{"en":"They drank the sap fresh from the tree as a tonic, knowing that it was an important source of energy.","zh":"他们把新鲜树液当作滋补饮品直接饮用，因为他们知道它是重要的能量来源。","source":"original","number":27}]},{"id":"maple-8d072c68df","term":"source","type":"word","sourceOrder":37,"zh":"来源、源泉","pos":"n.","ipa":"sɔːs","stars":2,"note":"消息来源；source of energy/income","paragraph":"听力原文","examples":[{"en":"They drank the sap fresh from the tree as a tonic, knowing that it was an important source of energy.","zh":"他们把新鲜树液当作滋补饮品直接饮用，因为他们知道它是重要的能量来源。","source":"original","number":27}]},{"id":"maple-e9486bfdc7","term":"reduce","type":"word","sourceOrder":38,"zh":"（熬煮使液体）浓缩","pos":"v.","ipa":"rɪˈdjuːs","stars":2,"note":"减少；降低；reduce costs/emissions","paragraph":"听力原文","examples":[{"en":"But for the most part, they reduced the syrup further and then cooled it so that it crystallized into sugar.","zh":"不过在大多数情况下，他们会进一步熬浓糖浆，再将其冷却，使它结晶成糖。","source":"original","number":28}]},{"id":"maple-d75ea506e4","term":"crystallize","type":"word","sourceOrder":39,"zh":"结晶成糖","pos":"v.","ipa":"ˈkrɪstəlaɪz","stars":4,"note":"想法变明确（crystallize an idea）；英式亦作 crystallise","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"crystal（水晶、晶体）＋-ize（使成为）","tip":"使液体里的糖形成晶体，就是结晶。","family":"crystal 晶体；crystallise 英式变体"},"examples":[{"en":"But for the most part, they reduced the syrup further and then cooled it so that it crystallized into sugar.","zh":"不过在大多数情况下，他们会进一步熬浓糖浆，再将其冷却，使它结晶成糖。","source":"original","number":28}]},{"id":"maple-6b85f5ff01","term":"indefinitely","type":"word","sourceOrder":40,"zh":"无限期地、长期地","pos":"adv.","ipa":"ɪnˈdefɪnətli","stars":4,"note":"postpone indefinitely 无限期推迟","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"in-（不）＋definite（确定的）＋-ly","tip":"没有确定的结束时间，即无限期地；不是“肯定地”。","family":"definite 确定的；indefinite 不确定的"},"examples":[{"en":"This was easy to carry and kept indefinitely.","zh":"这种糖便于携带，而且能长期保存。","source":"original","number":29}]},{"id":"maple-b21f4a2f9e","term":"settler","type":"word","sourceOrder":41,"zh":"定居者","pos":"n.","ipa":"ˈsetlə","stars":3,"note":"settle v. 定居/解决（争端）/结算","paragraph":"听力原文","examples":[{"en":"European settlers who arrived in Canada began to learn about the syrup from First Nations peoples and further expanded its uses.","zh":"来到加拿大的欧洲定居者开始向第一民族学习枫糖浆知识，并进一步开发其用途。","source":"original","number":30}]},{"id":"maple-16e78fd5f1","term":"expand","type":"word","sourceOrder":42,"zh":"扩展（用途）","pos":"v.","ipa":"ɪkˈspænd","stars":3,"note":"扩大规模；expand on 进一步说明","paragraph":"听力原文","examples":[{"en":"European settlers who arrived in Canada began to learn about the syrup from First Nations peoples and further expanded its uses.","zh":"来到加拿大的欧洲定居者开始向第一民族学习枫糖浆知识，并进一步开发其用途。","source":"original","number":30}]},{"id":"maple-bbe2479419","term":"incorporate","type":"word","sourceOrder":43,"zh":"加入、掺入（药物）","pos":"v.","ipa":"ɪnˈkɔːpəreɪt","stars":5,"note":"纳入：incorporate feedback into a plan","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"incorporate → incorporation；常用 into 补足加入对象","tip":"把糖浆加入药物中：incorporate it into medicine。","family":"incorporation 纳入；incorporated 被纳入的"},"examples":[{"en":"For example, they incorporated it into medicine of different kinds.","zh":"例如，他们将它加入各种药物中。","source":"original","number":31}]},{"id":"maple-02d7ad73ae","term":"medicine","type":"word","sourceOrder":44,"zh":"药物、药品（泛称）","pos":"n.","ipa":"ˈmedsən","stars":2,"note":"医学；study medicine 学医；这里作不可数泛称","paragraph":"听力原文","examples":[{"en":"For example, they incorporated it into medicine of different kinds.","zh":"例如，他们将它加入各种药物中。","source":"original","number":31}]},{"id":"maple-723f547ec9","term":"yeast","type":"word","sourceOrder":45,"zh":"酵母","pos":"n.","ipa":"jiːst","stars":3,"note":"fermentation 发酵相关词","paragraph":"听力原文","examples":[{"en":"They also discovered that by adding yeast to the sap, they could make a maple drink.","zh":"他们还发现，把酵母加入树液就能制成枫树液饮品。","source":"original","number":32}]},{"id":"maple-2c0cc0b66b","term":"toffee","type":"word","sourceOrder":46,"zh":"太妃糖","pos":"n.","ipa":"ˈtɒfi","stars":3,"note":"toffee-like：-like 表“类似……的”","paragraph":"听力原文","examples":[{"en":"And by throwing the hot syrup into the snow, they could make a toffee-like candy.","zh":"而且把热糖浆倒进雪里，还能做出类似太妃糖的糖果。","source":"original","number":33}]},{"id":"maple-00cb8b4fdd","term":"afford","type":"word","sourceOrder":47,"zh":"买得起","pos":"v.","ipa":"əˈfɔːd","stars":2,"note":"afford to do 有能力/负担得起做某事","paragraph":"听力原文","examples":[{"en":"For most people, it was the only type of sugar they could afford, since the only alternative was the sugar imported from the Caribbean, which was made from sugarcane.","zh":"对大多数人来说，这是唯一买得起的糖，因为当时唯一的替代品是从加勒比海进口、用甘蔗制成的糖。","source":"original","number":35}]},{"id":"maple-8fbe5b1f12","term":"alternative","type":"word","sourceOrder":48,"zh":"替代品","pos":"n./adj.","ipa":"ɔːlˈtɜːnətɪv","stars":3,"note":"可供选择的；alternative energy 替代能源","paragraph":"听力原文","examples":[{"en":"For most people, it was the only type of sugar they could afford, since the only alternative was the sugar imported from the Caribbean, which was made from sugarcane.","zh":"对大多数人来说，这是唯一买得起的糖，因为当时唯一的替代品是从加勒比海进口、用甘蔗制成的糖。","source":"original","number":35}]},{"id":"maple-4417b112fe","term":"import","type":"word","sourceOrder":49,"zh":"进口（的）","pos":"v.（本文为 imported 的词源动词）","ipa":"ɪmˈpɔːt","stars":3,"note":"名词与动词重音不同；exports 出口","paragraph":"听力原文","examples":[{"en":"For most people, it was the only type of sugar they could afford, since the only alternative was the sugar imported from the Caribbean, which was made from sugarcane.","zh":"对大多数人来说，这是唯一买得起的糖，因为当时唯一的替代品是从加勒比海进口、用甘蔗制成的糖。","source":"original","number":35}]},{"id":"maple-a64836575b","term":"Caribbean","type":"word","sourceOrder":50,"zh":"加勒比地区（的）","pos":"n./adj.","ipa":"ˌkærɪˈbiːən","stars":3,"note":"地名、地区名；本题 sugar 的产地","paragraph":"听力原文","examples":[{"en":"For most people, it was the only type of sugar they could afford, since the only alternative was the sugar imported from the Caribbean, which was made from sugarcane.","zh":"对大多数人来说，这是唯一买得起的糖，因为当时唯一的替代品是从加勒比海进口、用甘蔗制成的糖。","source":"original","number":35},{"en":"However, after eighteen eighty, the Canadian government decided to stop charging tax on Caribbean sugar, and this made it much cheaper.","zh":"然而，1880年以后，加拿大政府决定停止对加勒比海糖征税，使其大幅降价。","source":"original","number":37}]},{"id":"maple-6c017bf3e9","term":"sugarcane","type":"word","sourceOrder":51,"zh":"甘蔗","pos":"n.","ipa":"ˈʃʊɡəkeɪn","stars":3,"note":"sugar cane 也可分开写","paragraph":"听力原文","examples":[{"en":"For most people, it was the only type of sugar they could afford, since the only alternative was the sugar imported from the Caribbean, which was made from sugarcane.","zh":"对大多数人来说，这是唯一买得起的糖，因为当时唯一的替代品是从加勒比海进口、用甘蔗制成的糖。","source":"original","number":35}]},{"id":"maple-637f466060","term":"charge","type":"word","sourceOrder":52,"zh":"征收（税）","pos":"v./n.","ipa":"tʃɑːdʒ","stars":3,"note":"收费/指控/充电/负责；charge tax on","paragraph":"听力原文","examples":[{"en":"However, after eighteen eighty, the Canadian government decided to stop charging tax on Caribbean sugar, and this made it much cheaper.","zh":"然而，1880年以后，加拿大政府决定停止对加勒比海糖征税，使其大幅降价。","source":"original","number":37}]},{"id":"maple-33de21338d","term":"tax","type":"word","sourceOrder":53,"zh":"税、征税","pos":"n./v.","ipa":"tæks","stars":2,"note":"tax relief 减税；tax burden 税负","paragraph":"听力原文","examples":[{"en":"However, after eighteen eighty, the Canadian government decided to stop charging tax on Caribbean sugar, and this made it much cheaper.","zh":"然而，1880年以后，加拿大政府决定停止对加勒比海糖征税，使其大幅降价。","source":"original","number":37}]},{"id":"maple-3990a9020f","term":"cost-effective","type":"word","sourceOrder":54,"zh":"成本划算的","pos":"adj.","ipa":"ˌkɒst ɪˈfektɪv","stars":4,"note":"cost-effective solution 高性价比方案","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"cost（成本）＋effective（有效的）","tip":"花费与收益相称才是成本划算；不是价格越低越好。","family":"cost-effectiveness 成本效益；effective 有效的"},"examples":[{"en":"That meant it was no longer cost-effective to produce maple sugar.","zh":"这意味着生产枫糖不再具有成本效益。","source":"original","number":38}]},{"id":"maple-b7df28b3fc","term":"viable","type":"word","sourceOrder":55,"zh":"可行的、能持续经营的","pos":"adj.","ipa":"ˈvaɪəbəl","stars":4,"note":"viable option/business 商业或方案可行","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"viable → viability（可行性）","tip":"一种做法能实际运行并维持才 viable；联记 viable business。","family":"viability 可行性；a viable option 可行选项"},"examples":[{"en":"And so syrup making became the only viable industry remaining for Canadians.","zh":"因此，制作枫糖浆成为加拿大仍可持续经营的唯一相关产业。","source":"original","number":39}]},{"id":"maple-006a1d204e","term":"boom","type":"word","sourceOrder":56,"zh":"繁荣、激增","pos":"n./v.","ipa":"buːm","stars":3,"note":"经济繁荣/繁荣发展；爆炸声","paragraph":"听力原文","examples":[{"en":"At present, maple syrup is enjoying a boom.","zh":"目前枫糖浆产业正经历繁荣。","source":"original","number":41}]},{"id":"maple-0b145931a3","term":"decade","type":"word","sourceOrder":57,"zh":"十年","pos":"n.","ipa":"ˈdekeɪd","stars":3,"note":"over the last two decades 过去20年","paragraph":"听力原文","examples":[{"en":"In the last two decades, production has doubled in Canada.","zh":"过去二十年加拿大的枫糖浆产量翻了一番。","source":"original","number":42}]},{"id":"maple-196d52e44c","term":"double","type":"word","sourceOrder":58,"zh":"（产量）翻倍","pos":"v./adj.","ipa":"ˈdʌbəl","stars":2,"note":"两倍的；double as 兼作","paragraph":"听力原文","examples":[{"en":"In the last two decades, production has doubled in Canada.","zh":"过去二十年加拿大的枫糖浆产量翻了一番。","source":"original","number":42}]},{"id":"maple-a8ff6eaf00","term":"threat","type":"word","sourceOrder":59,"zh":"威胁","pos":"n.","ipa":"θret","stars":3,"note":"threaten v. 威胁；environmental threat","paragraph":"听力原文","examples":[{"en":"However, serious threats remain.","zh":"然而，严重的威胁依然存在。","source":"original","number":43}]},{"id":"maple-96cac08b2c","term":"harvest","type":"word","sourceOrder":60,"zh":"收成、收获","pos":"n./v.","ipa":"ˈhɑːvɪst","stars":3,"note":"采收；harvest data 收集数据（引申）","paragraph":"听力原文","examples":[{"en":"Like any agricultural product, the harvest is subject to such things as major storms or the arrival of invasive insects, both of which have happened, and these could destroy everything.","zh":"与其他农产品一样，收成会受到猛烈风暴或入侵性昆虫出现等因素的影响；这两类事件都发生过，而且可能造成毁灭性损失。","source":"original","number":44}]},{"id":"maple-79cf9e522d","term":"subject","type":"word","sourceOrder":61,"zh":"易受到……影响的（subject to）","pos":"adj.","ipa":"ˈsʌbdʒɪkt","stars":3,"note":"n. 科目/主题；subject to approval 须经批准","paragraph":"听力原文","examples":[{"en":"Like any agricultural product, the harvest is subject to such things as major storms or the arrival of invasive insects, both of which have happened, and these could destroy everything.","zh":"与其他农产品一样，收成会受到猛烈风暴或入侵性昆虫出现等因素的影响；这两类事件都发生过，而且可能造成毁灭性损失。","source":"original","number":44}]},{"id":"maple-d177b31384","term":"invasive","type":"word","sourceOrder":62,"zh":"入侵性的","pos":"adj.","ipa":"ɪnˈveɪsɪv","stars":4,"note":"invasive species 外来入侵物种；invasive procedure 侵入性手术","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"invade（入侵）→ invasive（入侵性的）","tip":"进入并扩散造成影响的昆虫；不要与 insect 昆虫本身混淆。","family":"invade 入侵；invasion 入侵"},"examples":[{"en":"Like any agricultural product, the harvest is subject to such things as major storms or the arrival of invasive insects, both of which have happened, and these could destroy everything.","zh":"与其他农产品一样，收成会受到猛烈风暴或入侵性昆虫出现等因素的影响；这两类事件都发生过，而且可能造成毁灭性损失。","source":"original","number":44}]},{"id":"maple-29a9acab39","term":"insect","type":"word","sourceOrder":63,"zh":"昆虫","pos":"n.","ipa":"ˈɪnsekt","stars":2,"note":"insects 为复数；与 insert /ɪnˈsɜːt/ 区分","paragraph":"听力原文","examples":[{"en":"Like any agricultural product, the harvest is subject to such things as major storms or the arrival of invasive insects, both of which have happened, and these could destroy everything.","zh":"与其他农产品一样，收成会受到猛烈风暴或入侵性昆虫出现等因素的影响；这两类事件都发生过，而且可能造成毁灭性损失。","source":"original","number":44}]},{"id":"maple-1de7cf37a0","term":"predict","type":"word","sourceOrder":64,"zh":"预测","pos":"v.","ipa":"prɪˈdɪkt","stars":3,"note":"prediction n. 预测；be predicted to","paragraph":"听力原文","examples":[{"en":"It is predicted with some certainty that in the longer term, climate change will also have an adverse effect on the sap run.","zh":"可以比较肯定地预测，从长远看，气候变化也会对树液流动产生不利影响。","source":"original","number":45}]},{"id":"maple-e2f81c892a","term":"certainty","type":"word","sourceOrder":65,"zh":"确定性、把握","pos":"n.","ipa":"ˈsɜːtənti","stars":3,"note":"with certainty 确定地；uncertainty 不确定性","paragraph":"听力原文","examples":[{"en":"It is predicted with some certainty that in the longer term, climate change will also have an adverse effect on the sap run.","zh":"可以比较肯定地预测，从长远看，气候变化也会对树液流动产生不利影响。","source":"original","number":45}]},{"id":"maple-560f40e270","term":"adverse","type":"word","sourceOrder":66,"zh":"不利的、负面的","pos":"adj.","ipa":"ˈædvɜːs","stars":4,"note":"adverse effects 负面影响；与 averse 厌恶的区别","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"整体记 adverse；与 adverse effect 搭配","tip":"不利影响 adverse effects；不是 averse（厌恶的）。","family":"adversely 不利地；adversity 逆境"},"examples":[{"en":"It is predicted with some certainty that in the longer term, climate change will also have an adverse effect on the sap run.","zh":"可以比较肯定地预测，从长远看，气候变化也会对树液流动产生不利影响。","source":"original","number":45}]},{"id":"maple-8d5a256d15","term":"factor","type":"word","sourceOrder":67,"zh":"因素","pos":"n.","ipa":"ˈfæktə","stars":3,"note":"contributing factor 促成因素；factor in v. 考虑进去","paragraph":"听力原文","examples":[{"en":"Then there are the social factors.","zh":"此外还有社会因素。","source":"original","number":46}]},{"id":"maple-2ad9f9c611","term":"labor-intensive","type":"word","sourceOrder":68,"zh":"劳动密集型的","pos":"adj.","ipa":"ˈleɪbə ɪnˌtensɪv","stars":4,"note":"labour-intensive 英式拼写；capital-intensive 资本密集型","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"labor（劳动）＋intensive（密集的）","tip":"需要投入大量人力；英式拼写 labour-intensive。","family":"labour 劳动；capital-intensive 资本密集的"},"examples":[{"en":"Producing maple syrup is a very labor-intensive process, making it an expensive purchase.","zh":"枫糖浆生产是劳动密集型过程，因此购买它的成本较高。","source":"original","number":47}]},{"id":"maple-76717c4a25","term":"purchase","type":"word","sourceOrder":69,"zh":"所购买的商品、购买行为","pos":"n./v.","ipa":"ˈpɜːtʃəs","stars":3,"note":"v. 购买；a costly purchase 昂贵的商品","paragraph":"听力原文","examples":[{"en":"Producing maple syrup is a very labor-intensive process, making it an expensive purchase.","zh":"枫糖浆生产是劳动密集型过程，因此购买它的成本较高。","source":"original","number":47}]},{"id":"maple-e1fb865c41","term":"competition","type":"word","sourceOrder":70,"zh":"（市场）竞争","pos":"n.","ipa":"ˌkɒmpəˈtɪʃən","stars":3,"note":"n. 比赛；competitive adj. 有竞争力的","paragraph":"听力原文","examples":[{"en":"And of equal concern is the fact that nowadays there's a lot of competition from cheaper, artificially flavored brands.","zh":"同样令人担忧的是，如今还存在来自更廉价的人工调味品牌的大量竞争。","source":"original","number":48}]},{"id":"maple-cd60e12a87","term":"artificially","type":"word","sourceOrder":71,"zh":"人工地（调味）","pos":"adv.","ipa":"ˌɑːtɪˈfɪʃəli","stars":4,"note":"artificial intelligence 人工智能；artificial light 人造光","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"artificial（人造的）＋-ly","tip":"人工调味 artificially flavored；不是天然风味。","family":"artificial 人造的；artificial flavouring 人工调味料"},"examples":[{"en":"And of equal concern is the fact that nowadays there's a lot of competition from cheaper, artificially flavored brands.","zh":"同样令人担忧的是，如今还存在来自更廉价的人工调味品牌的大量竞争。","source":"original","number":48}]},{"id":"maple-4cfde14573","term":"flavored / flavoured","type":"phrase","sourceOrder":72,"zh":"调味的","pos":"adj.","ipa":"ˈfleɪvəd","stars":3,"note":"flavour n. 味道；美式 flavored/英式 flavoured","paragraph":"听力原文","examples":[{"en":"And of equal concern is the fact that nowadays there's a lot of competition from cheaper, artificially flavored brands.","zh":"同样令人担忧的是，如今还存在来自更廉价的人工调味品牌的大量竞争。","source":"original","number":48}]},{"id":"maple-e0493adc0b","term":"obesity","type":"word","sourceOrder":73,"zh":"肥胖（问题）","pos":"n.","ipa":"əʊˈbiːsəti","stars":4,"note":"obese adj. 肥胖的；public health 常考","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"obese（肥胖的）→ obesity（肥胖）","tip":"形容词与名词结对记，注意词尾变化。","family":"obese 肥胖的；obesity 肥胖"},"examples":[{"en":"Furthermore, we're at a time when obesity is a major issue, making a product that is sixty-seven percent sugar increasingly difficult to sell.","zh":"此外，在肥胖已成为重大问题的时代，含糖量为67%的产品越来越难销售。","source":"original","number":49}]},{"id":"maple-9ac786ea2a","term":"increasingly","type":"word","sourceOrder":74,"zh":"越来越……","pos":"adv.","ipa":"ɪnˈkriːsɪŋli","stars":3,"note":"increasingly difficult/popular","paragraph":"听力原文","examples":[{"en":"Furthermore, we're at a time when obesity is a major issue, making a product that is sixty-seven percent sugar increasingly difficult to sell.","zh":"此外，在肥胖已成为重大问题的时代，含糖量为67%的产品越来越难销售。","source":"original","number":49}]},{"id":"maple-f6f150518a","term":"nevertheless","type":"word","sourceOrder":75,"zh":"尽管如此","pos":"adv.","ipa":"ˌnevəðəˈles","stars":3,"note":"= nonetheless；表示让步转折，常作路标","paragraph":"听力原文","examples":[{"en":"Nevertheless, there are reasons to be optimistic.","zh":"尽管如此，我们仍有理由保持乐观。","source":"original","number":50}]},{"id":"maple-db4c024ef9","term":"optimistic","type":"word","sourceOrder":76,"zh":"乐观的","pos":"adj.","ipa":"ˌɒptɪˈmɪstɪk","stars":3,"note":"optimism n. 乐观；pessimistic 悲观的","paragraph":"听力原文","examples":[{"en":"Nevertheless, there are reasons to be optimistic.","zh":"尽管如此，我们仍有理由保持乐观。","source":"original","number":50}]},{"id":"maple-d373a59de7","term":"producer","type":"word","sourceOrder":77,"zh":"生产商","pos":"n.","ipa":"prəˈdjuːsə","stars":3,"note":"produce v. 生产；produce n. 农产品（重音变化）","paragraph":"听力原文","examples":[{"en":"Producers are developing markets abroad.","zh":"生产商正在开拓海外市场。","source":"original","number":51}]},{"id":"maple-aee34dc012","term":"abroad","type":"word","sourceOrder":78,"zh":"在国外、向海外","pos":"adv.","ipa":"əˈbrɔːd","stars":3,"note":"study abroad 出国留学；markets abroad 海外市场","paragraph":"听力原文","examples":[{"en":"Producers are developing markets abroad.","zh":"生产商正在开拓海外市场。","source":"original","number":51}]},{"id":"maple-db8ec82e03","term":"export","type":"word","sourceOrder":79,"zh":"出口","pos":"v.","ipa":"ɪkˈspɔːt","stars":3,"note":"动词常后接 to；export products","paragraph":"听力原文","examples":[{"en":"Our syrup is currently being exported to over fifty countries.","zh":"我们的枫糖浆目前正出口至50多个国家。","source":"original","number":52}]},{"id":"maple-76852b2d9b","term":"enthusiastically","type":"word","sourceOrder":80,"zh":"热情地、积极地","pos":"adv.","ipa":"ɪnˌθjuːziˈæstɪkli","stars":5,"note":"enthusiasm 热情；enthusiastic adj.","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"enthusiastic（热情的）→ enthusiastically","tip":"形容词 -ic 变副词常对应 -ically；听重音处的 -as-。","family":"enthusiasm 热情；enthusiast 热心者"},"examples":[{"en":"Back here at home, chefs use it enthusiastically.","zh":"而在加拿大国内，厨师们也热衷使用枫糖浆。","source":"original","number":53}]},{"id":"maple-9b6a0f6d97","term":"calorie","type":"word","sourceOrder":81,"zh":"卡路里、热量单位","pos":"n.","ipa":"ˈkæləri","stars":3,"note":"high in calories 热量高","paragraph":"听力原文","examples":[{"en":"It's certainly high in calories, but it also contains proteins, minerals, and antioxidants.","zh":"它确实热量高，但也含有蛋白质、矿物质和抗氧化剂。","source":"original","number":54}]},{"id":"maple-6a4f3f7956","term":"mineral","type":"word","sourceOrder":82,"zh":"矿物质","pos":"n.","ipa":"ˈmɪnərəl","stars":3,"note":"矿产资源；mineral-rich 富含矿物质的","paragraph":"听力原文","examples":[{"en":"It's certainly high in calories, but it also contains proteins, minerals, and antioxidants.","zh":"它确实热量高，但也含有蛋白质、矿物质和抗氧化剂。","source":"original","number":54}]},{"id":"maple-06f75915b8","term":"antioxidant","type":"word","sourceOrder":83,"zh":"抗氧化剂","pos":"n.","ipa":"ˌæntiˈɒksɪdənt","stars":5,"note":"anti- 前缀表“抗”；anti-inflammatory 抗炎的","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"anti-（抗）＋oxidant（氧化剂）","tip":"对抗氧化作用的物质；先拆 anti-，再联想 oxidation 氧化。","family":"oxidation 氧化；antioxidant 抗氧化剂"},"examples":[{"en":"It's certainly high in calories, but it also contains proteins, minerals, and antioxidants.","zh":"它确实热量高，但也含有蛋白质、矿物质和抗氧化剂。","source":"original","number":54}]},{"id":"maple-d4d07992d6","term":"relatively","type":"word","sourceOrder":84,"zh":"相对地","pos":"adv.","ipa":"ˈrelətɪvli","stars":3,"note":"relative n. 亲属；adj. 相对的","paragraph":"听力原文","examples":[{"en":"As such, it is still relatively healthy when you compare it with sugar or corn syrup.","zh":"因此，与普通糖或玉米糖浆相比，它仍相对健康。","source":"original","number":55}]},{"id":"maple-da0e141e56","term":"primary","type":"word","sourceOrder":85,"zh":"首要的、主要的","pos":"adj.","ipa":"ˈpraɪməri","stars":3,"note":"初级的：primary school 小学","paragraph":"听力原文","examples":[{"en":"However, the primary reason for maple syrup's success around the world remains its taste.","zh":"然而，枫糖浆在世界各地获得成功的首要原因仍是它的味道。","source":"original","number":57}]},{"id":"maple-436ea5fda8","term":"root","type":"word","sourceOrder":86,"zh":"历史根源（比喻）","pos":"n.","ipa":"ruːt","stars":1,"note":"植物的根；root cause 根本原因","paragraph":"听力原文","examples":[{"en":"Canadians are proud of maple syrup and its deep roots in our history and geography.","zh":"加拿大人为枫糖浆及其在本国历史和地理中的深厚根基感到自豪。","source":"original","number":56}]},{"id":"maple-6420dd83e8","term":"taste","type":"word","sourceOrder":87,"zh":"味道、口味","pos":"n./v.","ipa":"teɪst","stars":1,"note":"品味：a taste for art；尝起来……","paragraph":"听力原文","examples":[{"en":"However, the primary reason for maple syrup's success around the world remains its taste.","zh":"然而，枫糖浆在世界各地获得成功的首要原因仍是它的味道。","source":"original","number":57}]},{"id":"maple-f062f3afaa","term":"be described as","type":"phrase","sourceOrder":88,"zh":"被描述为","pos":"搭配／句型","ipa":"biː dɪˈskraɪbd əz","stars":3,"note":"意义：被描述为；用于引出定义","paragraph":"听力原文","examples":[{"en":"Maple syrup can be described as very sweet.","zh":"枫糖浆可以被形容为非常甜。","source":"original","number":5},{"en":"The town is described as peaceful.","zh":"这个小镇被描述为宁静。","source":"supplemental"},{"en":"The process can be described as complex.","zh":"这一过程可被形容为复杂。","source":"supplemental"},{"en":"The lecture described the harvest as unpredictable.","zh":"讲座把收成描述为难以预测。","source":"supplemental"}]},{"id":"maple-0ce94f2df2","term":"pour A over B","type":"phrase","sourceOrder":89,"zh":"把A浇／倒在B上","pos":"搭配／句型","ipa":"pɔː eɪ ˈəʊvə biː","stars":3,"note":"意义：把A浇／倒在B上","paragraph":"听力原文","examples":[{"en":"Canadians pour it generously over things like pancakes for breakfast.","zh":"加拿大人早餐时常把它大量浇在煎饼等食物上。","source":"original","number":6},{"en":"Pour the sauce over the rice.","zh":"把酱汁浇在米饭上。","source":"supplemental"},{"en":"She poured water over the seeds.","zh":"她把水浇在种子上。","source":"supplemental"},{"en":"They poured hot syrup over the dessert.","zh":"他们把热糖浆浇在甜点上。","source":"supplemental"}]},{"id":"maple-1da1b4dc12","term":"be produced from","type":"phrase","sourceOrder":90,"zh":"由……制成","pos":"搭配／句型","ipa":"biː prəˈdjuːst frəm","stars":3,"note":"意义：由……制成；强调原料来源","paragraph":"听力原文","examples":[{"en":"The syrup is produced from the maple tree, and it actually comes from the tree's sap, which is the watery substance that comes out of the trunk of the tree when this is cut.","zh":"这种糖浆产自枫树，实际来源于枫树的树液；树液是一种含水物质，当树干被切开时会从中流出。","source":"original","number":7},{"en":"Paper is produced from wood.","zh":"纸由木材制成。","source":"supplemental"},{"en":"Some fuels are produced from crops.","zh":"有些燃料由农作物制成。","source":"supplemental"},{"en":"This oil is produced from seeds.","zh":"这种油由种子制成。","source":"supplemental"}]},{"id":"maple-478ec5d503","term":"in order for ... to ...","type":"phrase","sourceOrder":91,"zh":"为了使……能够……","pos":"搭配／句型","ipa":"ɪn ˈɔːdə fə … tə …","stars":3,"note":"意义：为了使……能够……","paragraph":"听力原文","examples":[{"en":"In order for enough sap to be produced, very special climate conditions are needed.","zh":"为了产生足够的树液，需要非常特殊的气候条件。","source":"original","number":8},{"en":"In order for crops to grow, they need sunlight.","zh":"为了让作物生长，它们需要阳光。","source":"supplemental"},{"en":"In order for the plan to work, everyone must agree.","zh":"为了让计划成功，人人都得同意。","source":"supplemental"},{"en":"In order for the river to recover, pollution must fall.","zh":"为了让河流恢复，污染必须减少。","source":"supplemental"}]},{"id":"maple-4fd5802ae0","term":"well below zero","type":"phrase","sourceOrder":92,"zh":"远低于零度","pos":"搭配／句型","ipa":"wel bɪˈləʊ ˈzɪərəʊ","stars":3,"note":"意义：远低于零度；well 表程度强调","paragraph":"听力原文","examples":[{"en":"In spring, the temperatures need to drop to well below zero at night, but then they need to rise sharply during the day, so they're hugely different over a twenty-four-hour period.","zh":"春季夜间温度需要降到远低于零度，白天又要急剧升高，因此24小时内昼夜温度差异很大。","source":"original","number":9},{"en":"The temperature fell well below zero.","zh":"温度远低于零度。","source":"supplemental"},{"en":"It stayed well below zero all night.","zh":"整晚气温都远低于零度。","source":"supplemental"},{"en":"Some trees survive well below zero.","zh":"有些树能在远低于零度的环境中存活。","source":"supplemental"}]},{"id":"maple-60107897f3","term":"rise sharply","type":"phrase","sourceOrder":93,"zh":"急剧上升","pos":"搭配／句型","ipa":"raɪz ˈʃɑːpli","stars":3,"note":"意义：急剧上升；图表/趋势题常用","paragraph":"听力原文","examples":[{"en":"In spring, the temperatures need to drop to well below zero at night, but then they need to rise sharply during the day, so they're hugely different over a twenty-four-hour period.","zh":"春季夜间温度需要降到远低于零度，白天又要急剧升高，因此24小时内昼夜温度差异很大。","source":"original","number":9},{"en":"Prices rose sharply in June.","zh":"六月价格急剧上涨。","source":"supplemental"},{"en":"Demand rose sharply after the launch.","zh":"发布后需求激增。","source":"supplemental"},{"en":"The temperature rose sharply at noon.","zh":"中午气温急剧上升。","source":"supplemental"}]},{"id":"maple-f4a7d2a401","term":"known as","type":"phrase","sourceOrder":94,"zh":"被称为……","pos":"搭配／句型","ipa":"nəʊn əz","stars":3,"note":"意义：被称为……","paragraph":"听力原文","examples":[{"en":"The indigenous peoples of North America, known as the First Nations, discovered the maple's secret long before the Europeans arrived.","zh":"北美原住民（称为 First Nations，即“第一民族”）早在欧洲人到来很久之前就发现了枫树的秘密。","source":"original","number":11},{"en":"The city is known as a cultural centre.","zh":"这座城市被称为文化中心。","source":"supplemental"},{"en":"The process is known as fermentation.","zh":"这个过程叫作发酵。","source":"supplemental"},{"en":"The group is known as the First Nations.","zh":"这个群体被称为第一民族。","source":"supplemental"}]},{"id":"maple-820bac2287","term":"long before","type":"phrase","sourceOrder":95,"zh":"早在……很久之前","pos":"搭配／句型","ipa":"lɒŋ bɪˈfɔː","stars":3,"note":"意义：早在……很久之前","paragraph":"听力原文","examples":[{"en":"The indigenous peoples of North America, known as the First Nations, discovered the maple's secret long before the Europeans arrived.","zh":"北美原住民（称为 First Nations，即“第一民族”）早在欧洲人到来很久之前就发现了枫树的秘密。","source":"original","number":11},{"en":"People traded here long before the railway existed.","zh":"铁路出现很久前人们就在这里交易。","source":"supplemental"},{"en":"The method was used long before modern machines.","zh":"现代机器出现之前很久人们就在用这种方法。","source":"supplemental"},{"en":"She arrived long before the lecture started.","zh":"她在讲座开始很久前就到了。","source":"supplemental"}]},{"id":"maple-3e2194f688","term":"turn A into B","type":"phrase","sourceOrder":96,"zh":"把A转变成B","pos":"搭配／句型","ipa":"tɜːn eɪ ˈɪntə biː","stars":3,"note":"意义：把A转变成B","paragraph":"听力原文","examples":[{"en":"His wife used this sap to boil meat, and the heat turned it into a sweet syrup, which they found delicious.","zh":"他的妻子用这树液煮肉，热量使它变成甜糖浆，他们觉得味道很好。","source":"original","number":14},{"en":"But like the First Nations, they turned most of their sap into maple sugar.","zh":"但他们和第一民族一样，仍将大部分树液做成枫糖。","source":"original","number":34},{"en":"Heat turns ice into water.","zh":"热量把冰变成水。","source":"supplemental"},{"en":"The project turned an old factory into a museum.","zh":"该项目将旧工厂改造成博物馆。","source":"supplemental"},{"en":"Farmers turn sap into syrup.","zh":"农民把树液熬成糖浆。","source":"supplemental"}]},{"id":"maple-da85e3d008","term":"whether or not","type":"phrase","sourceOrder":97,"zh":"不管是否","pos":"搭配／句型","ipa":"ˈweðə ɔː nɒt","stars":3,"note":"意义：不管是否","paragraph":"听力原文","examples":[{"en":"Whether or not that story is true, we do know that the maple tree was very important to First Nations peoples for hundreds of years.","zh":"无论这个故事是真是假，我们确实知道数百年来枫树对第一民族非常重要。","source":"original","number":15},{"en":"We will continue whether or not it rains.","zh":"无论下不下雨我们都继续。","source":"supplemental"},{"en":"Whether or not the claim is true, it is influential.","zh":"无论说法是否真实，它都很有影响。","source":"supplemental"},{"en":"She must decide whether or not to apply.","zh":"她必须决定是否申请。","source":"supplemental"}]},{"id":"maple-9c980b15a1","term":"set up camp","type":"phrase","sourceOrder":98,"zh":"搭建营地、扎营","pos":"搭配／句型","ipa":"set ʌp kæmp","stars":3,"note":"意义：搭建营地、扎营","paragraph":"听力原文","examples":[{"en":"Whole families would migrate to the areas where the maple trees grew and set up camp there.","zh":"整个家族过去常常迁往枫树生长的地区，并在那里扎营。","source":"original","number":17},{"en":"They set up camp near the lake.","zh":"他们在湖边扎营。","source":"supplemental"},{"en":"The group set up camp before sunset.","zh":"队伍在日落前扎营。","source":"supplemental"},{"en":"Explorers set up camp beside the forest.","zh":"探险者在林边设营。","source":"supplemental"}]},{"id":"maple-d99d8df484","term":"concentrate the sap","type":"phrase","sourceOrder":99,"zh":"浓缩树液","pos":"搭配／句型","ipa":"ˈkɒnsəntreɪt ðə sæp","stars":4,"note":"意义：浓缩树液；concentrate 有别于“集中精神”","paragraph":"听力原文","examples":[{"en":"Then they needed to concentrate the sap, removing some of the water from it to create syrup.","zh":"接着他们需要浓缩树液，去除部分水分以制成糖浆。","source":"original","number":19},{"en":"They concentrated the sap by heating it.","zh":"他们通过加热浓缩树液。","source":"supplemental"},{"en":"Workers concentrate the liquid before bottling it.","zh":"工人在装瓶前浓缩液体。","source":"supplemental"},{"en":"The factory concentrates fruit juice.","zh":"工厂生产浓缩果汁。","source":"supplemental"}]},{"id":"maple-c0a08cda50","term":"be exposed to","type":"phrase","sourceOrder":100,"zh":"暴露于、接触到","pos":"搭配／句型","ipa":"biː ɪkˈspəʊzd tə","stars":3,"note":"意义：暴露于、接触到","paragraph":"词汇与语块","examples":[{"en":"Plants were exposed to low temperatures.","zh":"植物暴露在低温下。","source":"supplemental"},{"en":"Children should not be exposed to harmful fumes.","zh":"儿童不应接触有害烟雾。","source":"supplemental"},{"en":"The metal was exposed to rain.","zh":"这种金属淋雨了。","source":"supplemental"}]},{"id":"maple-961f09c87d","term":"a layer of","type":"phrase","sourceOrder":101,"zh":"一层……","pos":"搭配／句型","ipa":"ə ˈleɪə əv","stars":3,"note":"意义：一层……；layer 后常考材料名词","paragraph":"词汇与语块","examples":[{"en":"A layer of dust covered the table.","zh":"桌面盖了一层灰。","source":"supplemental"},{"en":"A layer of ice formed overnight.","zh":"一夜之间形成一层冰。","source":"supplemental"},{"en":"The cake has a layer of cream.","zh":"蛋糕有一层奶油。","source":"supplemental"}]},{"id":"maple-ae4bca7958","term":"for the most part","type":"phrase","sourceOrder":102,"zh":"总体而言","pos":"搭配／句型","ipa":"fə ðə məʊst pɑːt","stars":3,"note":"意义：总体而言；大多数情况下","paragraph":"听力原文","examples":[{"en":"But for the most part, they reduced the syrup further and then cooled it so that it crystallized into sugar.","zh":"不过在大多数情况下，他们会进一步熬浓糖浆，再将其冷却，使它结晶成糖。","source":"original","number":28},{"en":"For the most part, the students agreed.","zh":"大多数学生表示同意。","source":"supplemental"},{"en":"The road is safe for the most part.","zh":"这条路总体上安全。","source":"supplemental"},{"en":"For the most part, the sap became sugar.","zh":"大多数树液被制成糖。","source":"supplemental"}]},{"id":"maple-0cb51be0c1","term":"so that","type":"phrase","sourceOrder":103,"zh":"以便","pos":"搭配／句型","ipa":"səʊ ðæt","stars":3,"note":"意义：以便；因此（视语境）","paragraph":"听力原文","examples":[{"en":"But for the most part, they reduced the syrup further and then cooled it so that it crystallized into sugar.","zh":"不过在大多数情况下，他们会进一步熬浓糖浆，再将其冷却，使它结晶成糖。","source":"original","number":28},{"en":"He spoke slowly so that everyone could follow.","zh":"他讲得慢，以便人人跟上。","source":"supplemental"},{"en":"The liquid was cooled so that it crystallized.","zh":"液体冷却后因而结晶。","source":"supplemental"},{"en":"She took notes so that she could review later.","zh":"她记笔记以便日后复习。","source":"supplemental"}]},{"id":"maple-2a33cb591f","term":"incorporate A into B","type":"phrase","sourceOrder":104,"zh":"把A纳入/加入B","pos":"搭配／句型","ipa":"ɪnˈkɔːpəreɪt eɪ ˈɪntə biː","stars":4,"note":"意义：把A纳入/加入B","paragraph":"听力原文","examples":[{"en":"For example, they incorporated it into medicine of different kinds.","zh":"例如，他们将它加入各种药物中。","source":"original","number":31},{"en":"The school incorporated games into lessons.","zh":"学校将游戏融入课程。","source":"supplemental"},{"en":"They incorporated herbs into the medicine.","zh":"他们把草药加入药品。","source":"supplemental"},{"en":"We should incorporate feedback into the report.","zh":"我们应把反馈纳入报告。","source":"supplemental"}]},{"id":"maple-f8e9fe2066","term":"by + -ing","type":"phrase","sourceOrder":105,"zh":"通过做某事","pos":"搭配／句型","ipa":"baɪ ɪŋ","stars":3,"note":"意义：通过做某事；方法状语","paragraph":"听力原文","examples":[{"en":"They also discovered that by adding yeast to the sap, they could make a maple drink.","zh":"他们还发现，把酵母加入树液就能制成枫树液饮品。","source":"original","number":32},{"en":"You can improve by practising daily.","zh":"你可以通过每日练习提高。","source":"supplemental"},{"en":"They made candy by cooling hot syrup.","zh":"他们通过冷却热糖浆制糖。","source":"supplemental"},{"en":"We save energy by turning off lights.","zh":"我们通过关灯节能。","source":"supplemental"}]},{"id":"maple-6619f9d2d1","term":"afford to do","type":"phrase","sourceOrder":106,"zh":"负担得起/有条件做……","pos":"搭配／句型","ipa":"əˈfɔːd tə duː","stars":3,"note":"意义：负担得起/有条件做…… 本文原句为 could afford，后接省略了的购买对象；afford to do 是扩展搭配。","paragraph":"听力原文","examples":[{"en":"For most people, it was the only type of sugar they could afford, since the only alternative was the sugar imported from the Caribbean, which was made from sugarcane.","zh":"对大多数人来说，这是唯一买得起的糖，因为当时唯一的替代品是从加勒比海进口、用甘蔗制成的糖。","source":"original","number":35},{"en":"Many families cannot afford to travel.","zh":"许多家庭负担不起旅行。","source":"supplemental"},{"en":"The company can afford to hire staff.","zh":"公司有能力招聘员工。","source":"supplemental"},{"en":"We cannot afford to miss the deadline.","zh":"我们不能承担错过截止日期的后果。","source":"supplemental"}]},{"id":"maple-fcb42d1ee6","term":"charge tax on","type":"phrase","sourceOrder":107,"zh":"对……征税","pos":"搭配／句型","ipa":"tʃɑːdʒ tæks ɒn","stars":3,"note":"意义：对……征税","paragraph":"听力原文","examples":[{"en":"However, after eighteen eighty, the Canadian government decided to stop charging tax on Caribbean sugar, and this made it much cheaper.","zh":"然而，1880年以后，加拿大政府决定停止对加勒比海糖征税，使其大幅降价。","source":"original","number":37},{"en":"The government charges tax on imports.","zh":"政府对进口品征税。","source":"supplemental"},{"en":"Some countries charge tax on sugary drinks.","zh":"一些国家对含糖饮料征税。","source":"supplemental"},{"en":"They stopped charging tax on this product.","zh":"他们停止对该产品征税。","source":"supplemental"}]},{"id":"maple-291ce979c7","term":"no longer cost-effective","type":"phrase","sourceOrder":108,"zh":"不再经济划算","pos":"搭配／句型","ipa":"nəʊ ˈlɒŋɡə ˌkɒst ɪˈfektɪv","stars":3,"note":"意义：不再经济划算","paragraph":"听力原文","examples":[{"en":"That meant it was no longer cost-effective to produce maple sugar.","zh":"这意味着生产枫糖不再具有成本效益。","source":"original","number":38},{"en":"The machine is no longer cost-effective.","zh":"这台机器已不划算。","source":"supplemental"},{"en":"It became no longer cost-effective to transport goods by air.","zh":"空运货物变得不再划算。","source":"supplemental"},{"en":"The old method is no longer cost-effective.","zh":"旧方法不再经济实惠。","source":"supplemental"}]},{"id":"maple-57b41f081b","term":"ever since","type":"phrase","sourceOrder":109,"zh":"从那以后一直","pos":"搭配／句型","ipa":"ˈevə sɪns","stars":3,"note":"意义：从那以后一直","paragraph":"听力原文","examples":[{"en":"And that's what we've been doing ever since.","zh":"从那时起我们便一直在做这件事。","source":"original","number":40},{"en":"She moved here in 2020 and has lived here ever since.","zh":"她2020年搬来后一直住在这里。","source":"supplemental"},{"en":"The rule changed, and prices have fallen ever since.","zh":"规则改变后价格一直下跌。","source":"supplemental"},{"en":"He started studying then and has continued ever since.","zh":"他当时开始学习，此后一直坚持。","source":"supplemental"}]},{"id":"maple-bf20e297f2","term":"be subject to","type":"phrase","sourceOrder":110,"zh":"易受……影响","pos":"搭配／句型","ipa":"biː ˈsʌbdʒɪkt tə","stars":4,"note":"意义：易受……影响；须遵守……","paragraph":"听力原文","examples":[{"en":"Like any agricultural product, the harvest is subject to such things as major storms or the arrival of invasive insects, both of which have happened, and these could destroy everything.","zh":"与其他农产品一样，收成会受到猛烈风暴或入侵性昆虫出现等因素的影响；这两类事件都发生过，而且可能造成毁灭性损失。","source":"original","number":44},{"en":"The harvest is subject to drought.","zh":"收成容易受干旱影响。","source":"supplemental"},{"en":"Applications are subject to approval.","zh":"申请须经批准。","source":"supplemental"},{"en":"Flight times are subject to change.","zh":"航班时间可能变更。","source":"supplemental"}]},{"id":"maple-cb1578d505","term":"have an adverse effect on","type":"phrase","sourceOrder":111,"zh":"对……产生不利影响","pos":"搭配／句型","ipa":"həv ən ˈædvɜːs ɪˈfekt ɒn","stars":3,"note":"意义：对……产生不利影响","paragraph":"听力原文","examples":[{"en":"It is predicted with some certainty that in the longer term, climate change will also have an adverse effect on the sap run.","zh":"可以比较肯定地预测，从长远看，气候变化也会对树液流动产生不利影响。","source":"original","number":45},{"en":"Noise has an adverse effect on sleep.","zh":"噪声会对睡眠产生不利影响。","source":"supplemental"},{"en":"Drought may have an adverse effect on crops.","zh":"干旱可能损害作物。","source":"supplemental"},{"en":"Stress can have an adverse effect on memory.","zh":"压力可能不利于记忆。","source":"supplemental"}]},{"id":"maple-a09297a927","term":"of equal concern","type":"phrase","sourceOrder":112,"zh":"同样令人担忧","pos":"搭配／句型","ipa":"əv ˈiːkwəl kənˈsɜːn","stars":3,"note":"意义：同样令人担忧；可引导倒装","paragraph":"听力原文","examples":[{"en":"And of equal concern is the fact that nowadays there's a lot of competition from cheaper, artificially flavored brands.","zh":"同样令人担忧的是，如今还存在来自更廉价的人工调味品牌的大量竞争。","source":"original","number":48},{"en":"Of equal concern is the lack of funding.","zh":"资金短缺同样令人担忧。","source":"supplemental"},{"en":"Of equal concern is the rise in costs.","zh":"成本上涨同样值得关注。","source":"supplemental"},{"en":"Of equal concern is public health.","zh":"公共卫生也同样值得关注。","source":"supplemental"}]},{"id":"maple-01dc30e84b","term":"a lot of competition from","type":"phrase","sourceOrder":113,"zh":"面临来自……的大量竞争","pos":"搭配／句型","ipa":"ə lɒt əv ˌkɒmpəˈtɪʃən frəm","stars":4,"note":"意义：面临来自……的大量竞争","paragraph":"听力原文","examples":[{"en":"And of equal concern is the fact that nowadays there's a lot of competition from cheaper, artificially flavored brands.","zh":"同样令人担忧的是，如今还存在来自更廉价的人工调味品牌的大量竞争。","source":"original","number":48},{"en":"Local shops face competition from chains.","zh":"本地商店面临连锁店竞争。","source":"supplemental"},{"en":"The brand faces a lot of competition from rivals.","zh":"该品牌面对竞争对手的激烈竞争。","source":"supplemental"},{"en":"Traditional products face competition from cheap alternatives.","zh":"传统产品受到廉价替代品竞争。","source":"supplemental"}]},{"id":"maple-29ab3e23ca","term":"reasons to be optimistic","type":"phrase","sourceOrder":114,"zh":"有理由保持乐观","pos":"搭配／句型","ipa":"ˈriːzənz tə biː ˌɒptɪˈmɪstɪk","stars":3,"note":"意义：有理由保持乐观","paragraph":"听力原文","examples":[{"en":"Nevertheless, there are reasons to be optimistic.","zh":"尽管如此，我们仍有理由保持乐观。","source":"original","number":50},{"en":"There are reasons to be optimistic about recovery.","zh":"有理由对复苏保持乐观。","source":"supplemental"},{"en":"Better results give us reasons to be optimistic.","zh":"更好的结果让我们有理由乐观。","source":"supplemental"},{"en":"The new market offers reasons to be optimistic.","zh":"新市场带来乐观理由。","source":"supplemental"}]},{"id":"maple-09fb0b0677","term":"develop markets abroad","type":"phrase","sourceOrder":115,"zh":"开拓海外市场","pos":"搭配／句型","ipa":"dɪˈveləp ˈmɑːkɪts əˈbrɔːd","stars":3,"note":"意义：开拓海外市场","paragraph":"听力原文","examples":[{"en":"Producers are developing markets abroad.","zh":"生产商正在开拓海外市场。","source":"original","number":51},{"en":"The company plans to develop markets abroad.","zh":"公司计划开拓海外市场。","source":"supplemental"},{"en":"Small producers struggle to develop markets abroad.","zh":"小生产商难以开拓海外市场。","source":"supplemental"},{"en":"Online sales help firms develop markets abroad.","zh":"线上销售帮助企业拓展海外市场。","source":"supplemental"}]},{"id":"maple-f6dfb6ef5d","term":"be high in","type":"phrase","sourceOrder":116,"zh":"富含……","pos":"搭配／句型","ipa":"biː haɪ ɪn","stars":3,"note":"意义：富含……；也可表示某指标很高","paragraph":"词汇与语块","examples":[{"en":"Nuts are high in protein.","zh":"坚果富含蛋白质。","source":"supplemental"},{"en":"The dessert is high in sugar.","zh":"这种甜点含糖量高。","source":"supplemental"},{"en":"Maple syrup is high in calories.","zh":"枫糖浆热量高。","source":"supplemental"}]},{"id":"maple-bc9fb51b01","term":"compare A with B","type":"phrase","sourceOrder":117,"zh":"把A与B比较","pos":"搭配／句型","ipa":"kəmˈpeə eɪ wɪð biː","stars":3,"note":"意义：把A与B比较","paragraph":"听力原文","examples":[{"en":"As such, it is still relatively healthy when you compare it with sugar or corn syrup.","zh":"因此，与普通糖或玉米糖浆相比，它仍相对健康。","source":"original","number":55},{"en":"Compare the price with last year’s.","zh":"把价格与去年比较。","source":"supplemental"},{"en":"We compared the results with the control group.","zh":"我们把结果与对照组比较。","source":"supplemental"},{"en":"Compare syrup with ordinary sugar.","zh":"把糖浆与普通糖进行比较。","source":"supplemental"}]},{"id":"maple-9fbb339a7c","term":"be proud of","type":"phrase","sourceOrder":118,"zh":"为……感到自豪","pos":"搭配／句型","ipa":"biː praʊd əv","stars":3,"note":"意义：为……感到自豪","paragraph":"听力原文","examples":[{"en":"Canadians are proud of maple syrup and its deep roots in our history and geography.","zh":"加拿大人为枫糖浆及其在本国历史和地理中的深厚根基感到自豪。","source":"original","number":56},{"en":"Residents are proud of their history.","zh":"居民为本地历史感到自豪。","source":"supplemental"},{"en":"She is proud of her progress.","zh":"她为自己的进步自豪。","source":"supplemental"},{"en":"The country is proud of its local products.","zh":"该国为本土产品感到自豪。","source":"supplemental"}]},{"id":"maple-e53a16cfd0","term":"deep roots in","type":"phrase","sourceOrder":119,"zh":"在……中有深厚根基","pos":"搭配／句型","ipa":"diːp ruːts ɪn","stars":3,"note":"意义：在……中有深厚根基","paragraph":"听力原文","examples":[{"en":"Canadians are proud of maple syrup and its deep roots in our history and geography.","zh":"加拿大人为枫糖浆及其在本国历史和地理中的深厚根基感到自豪。","source":"original","number":56},{"en":"The festival has deep roots in local culture.","zh":"该节日深植本地文化。","source":"supplemental"},{"en":"The practice has deep roots in history.","zh":"这一习俗有深厚历史根基。","source":"supplemental"},{"en":"The dish has deep roots in the region.","zh":"这道菜深深扎根于该地区。","source":"supplemental"}]},{"id":"maple-adf6ed5165","term":"maple syrup","type":"phrase","sourceOrder":120,"zh":"枫糖浆","pos":"搭配／词块","ipa":"ˈmeɪpəl ˈsɪrəp","stars":3,"note":"优先整块识别，不要只记住其中一个单词。","paragraph":"听力原文","examples":[{"en":"Maple syrup can be described as very sweet.","zh":"枫糖浆可以被形容为非常甜。","source":"original","number":5}]},{"id":"maple-49ac61c516","term":"invasive insects","type":"phrase","sourceOrder":121,"zh":"入侵性昆虫","pos":"搭配／词块","ipa":"ɪnˈveɪsɪv ˈɪnsekts","stars":4,"note":"优先整块识别，不要只记住其中一个单词。","paragraph":"听力原文","examples":[{"en":"Like any agricultural product, the harvest is subject to such things as major storms or the arrival of invasive insects, both of which have happened, and these could destroy everything.","zh":"与其他农产品一样，收成会受到猛烈风暴或入侵性昆虫出现等因素的影响；这两类事件都发生过，而且可能造成毁灭性损失。","source":"original","number":44}]},{"id":"maple-05b535bb57","term":"artificially flavored brands","type":"phrase","sourceOrder":122,"zh":"人工调味的品牌产品","pos":"搭配／词块","ipa":"ˌɑːtɪˈfɪʃəli ˈfleɪvəd brændz","stars":3,"note":"优先整块识别，不要只记住其中一个单词。","paragraph":"听力原文","examples":[{"en":"And of equal concern is the fact that nowadays there's a lot of competition from cheaper, artificially flavored brands.","zh":"同样令人担忧的是，如今还存在来自更廉价的人工调味品牌的大量竞争。","source":"original","number":48}]}],"sentences":[{"en":"Section four.","zh":"第四部分。","speaker":"主讲人","paragraph":"听力原文","note":"词块：section = 试卷部分\n结构／听力：考试提示；不是答题内容。"},{"en":"You will hear a lecture on a very popular Canadian food product called maple syrup.","zh":"你将听到一场有关加拿大广受欢迎的食品——枫糖浆的讲座。","speaker":"主讲人","paragraph":"听力原文","note":"词块：lecture 讲座；product 产品；called ... 名为……\n结构／听力：called maple syrup 为过去分词短语，后置修饰 product；先明确主题领域：农业、食品、历史。"},{"en":"First, you have some time to look at questions thirty-one to forty on page seven.","zh":"首先，你有一些时间查看第七页的第31至40题。","speaker":"主讲人","paragraph":"听力原文","note":"词块：look at questions 预览题目\n结构／听力：此时要看栏目、空格两侧，不要逐字翻译整份笔记。"},{"en":"Now listen carefully and answer questions thirty-one to forty.","zh":"现在仔细听并回答第31至40题。","speaker":"主讲人","paragraph":"听力原文","note":"词块：listen carefully 仔细听\n结构／听力：听力开始后以题目顺序推进，不能因为某一空卡住而错过后续答案。"},{"en":"Maple syrup can be described as very sweet.","zh":"枫糖浆可以被形容为非常甜。","speaker":"主讲人","paragraph":"听力原文","note":"词块：be described as 被描述为；syrup 糖浆\n结构／听力：被动结构 can be + past participle；对应 Description。"},{"en":"Canadians pour it generously over things like pancakes for breakfast.","zh":"加拿大人早餐时常把它大量浇在煎饼等食物上。","speaker":"主讲人","paragraph":"听力原文","note":"词块：pour A over B 把A浇在B上；generously 大量地\n结构／听力：generously 在此指“量多”，不是“慷慨的性格”；pancakes 为背景而非设空。"},{"en":"The syrup is produced from the maple tree, and it actually comes from the tree's sap, which is the watery substance that comes out of the trunk of the tree when this is cut.","zh":"这种糖浆产自枫树，实际来源于枫树的树液；树液是一种含水物质，当树干被切开时会从中流出。","speaker":"主讲人","paragraph":"听力原文","note":"词块：be produced from 来源于；sap 树液；trunk 树干；watery 含水的\n结构／听力：主干由 and 连接；which 引导非限制性定语从句解释 sap；that ... 修饰 substance；when ... 时间从句；this = trunk。"},{"en":"In order for enough sap to be produced, very special climate conditions are needed.","zh":"为了产生足够的树液，需要非常特殊的气候条件。","speaker":"主讲人","paragraph":"听力原文","note":"词块：in order for ... to do 为使……；climate conditions 气候条件\n结构／听力：目的结构 in order for + 名词 + to be done；主句被动。暗示下一句将解释气候差异。"},{"en":"In spring, the temperatures need to drop to well below zero at night, but then they need to rise sharply during the day, so they're hugely different over a twenty-four-hour period.","zh":"春季夜间温度需要降到远低于零度，白天又要急剧升高，因此24小时内昼夜温度差异很大。","speaker":"主讲人","paragraph":"听力原文","note":"词块：well below zero 远低于零度；rise sharply 急剧上升；hugely different 差异巨大\n结构／听力：drop...but rise...so different：对比—结果逻辑；Q31 的形容词答案 different 出现在 so 后。"},{"en":"And that's exactly what happens in northeastern Canada every spring.","zh":"而加拿大东北部每年春天恰好就有这样的气候。","speaker":"主讲人","paragraph":"听力原文","note":"词块：exactly 恰好；northeastern 东北部的\n结构／听力：what happens 为表语从句；that 回指显著昼夜温差。"},{"en":"The indigenous peoples of North America, known as the First Nations, discovered the maple's secret long before the Europeans arrived.","zh":"北美原住民（称为 First Nations，即“第一民族”）早在欧洲人到来很久之前就发现了枫树的秘密。","speaker":"主讲人","paragraph":"听力原文","note":"词块：indigenous peoples 原住民族群；known as 被称为；long before 远在……之前\n结构／听力：known as ... 插入的过去分词解释身份；long before 为时间对比；历史背景。"},{"en":"Early folk stories say it was first discovered by a chief who threw his tomahawk, which is similar to an ax, into the trunk of a tree.","zh":"早期民间故事称，一位酋长把战斧掷入树干，从而首先发现了枫树液；战斧类似斧头。","speaker":"主讲人","paragraph":"听力原文","note":"词块：folk stories 民间故事；chief 酋长；tomahawk 战斧；be similar to 类似\n结构／听力：say 后省略 that；who 修饰 chief；which 解释 tomahawk；故事引出 Q32。"},{"en":"Clear sap started to run from the cut.","zh":"清澈的树液开始从切口处流出来。","speaker":"主讲人","paragraph":"听力原文","note":"词块：run 流动（熟词生义）；cut 切口（名词）\n结构／听力：run 不指“奔跑”；from the cut 指从树干伤口流出。"},{"en":"His wife used this sap to boil meat, and the heat turned it into a sweet syrup, which they found delicious.","zh":"他的妻子用这树液煮肉，热量使它变成甜糖浆，他们觉得味道很好。","speaker":"主讲人","paragraph":"听力原文","note":"词块：use sth to do 用……做……；boil meat 煮肉；turn A into B 将A变成B\n结构／听力：Q32 题干 used to cook ___ ↔ used sap to boil meat，答案 meat；which 引导补充说明。"},{"en":"Whether or not that story is true, we do know that the maple tree was very important to First Nations peoples for hundreds of years.","zh":"无论这个故事是真是假，我们确实知道数百年来枫树对第一民族非常重要。","speaker":"主讲人","paragraph":"听力原文","note":"词块：whether or not 无论是否；do know 确实知道\n结构／听力：whether or not 引导让步状语；do 强调 know；历史传说与可确认事实要区分。"},{"en":"Collecting the sap each spring became a tradition among them.","zh":"每年春天采集树液逐渐成为他们的一项传统。","speaker":"主讲人","paragraph":"听力原文","note":"词块：collect 收集；tradition 传统\n结构／听力：动名词短语 Collecting the sap 作主语；Q33 developed into a ___ ↔ became a tradition。"},{"en":"Whole families would migrate to the areas where the maple trees grew and set up camp there.","zh":"整个家族过去常常迁往枫树生长的地区，并在那里扎营。","speaker":"主讲人","paragraph":"听力原文","note":"词块：would migrate 过去常常迁移；set up camp 扎营\n结构／听力：would 在此表示过去的习惯，不是推测；where 引导定语从句修饰 areas。"},{"en":"They collected the sap from the trees using buckets.","zh":"他们用桶从枫树上采集树液。","speaker":"主讲人","paragraph":"听力原文","note":"词块：bucket 桶；using buckets 用桶\n结构／听力：using ... 现在分词表方式；这句是下一段浓缩方法的前置步骤。"},{"en":"Then they needed to concentrate the sap, removing some of the water from it to create syrup.","zh":"接着他们需要浓缩树液，去除部分水分以制成糖浆。","speaker":"主讲人","paragraph":"听力原文","note":"词块：concentrate 浓缩（熟词生义）；remove 去除\n结构／听力：removing ... 解释 concentrate 的具体方式；to create 表目的。"},{"en":"They had two ways of doing this.","zh":"他们有两种办法来完成这一步。","speaker":"主讲人","paragraph":"听力原文","note":"词块：two ways 两种方式\n结构／听力：极强的结构路标：下一句 first method → Q34，再下一种 → Q35。"},{"en":"One way was to drop hot stones from a fire into the buckets to create steam.","zh":"其中一种办法是把从火里取出的热石头放进桶里，从而产生蒸汽。","speaker":"主讲人","paragraph":"听力原文","note":"词块：drop ... into 放入；steam 蒸汽\n结构／听力：One way 对应方法一；to create steam 对应 Q34 produce ___；答案 steam，注意拼写不是 steem。"},{"en":"If repeated often enough, this would eventually concentrate the syrup.","zh":"如果重复足够多次，最终就能把糖浆浓缩。","speaker":"主讲人","paragraph":"听力原文","note":"词块：repeated 反复进行；eventually 最终\n结构／听力：If repeated = If it was repeated，省略条件句；this 指热石头产生蒸汽的方法。"},{"en":"Another method that they used to concentrate the syrup was to leave the sap outside overnight, exposed to freezing temperatures.","zh":"另一种浓缩方法是把树液放在户外过夜，使其暴露在冰冻温度下。","speaker":"主讲人","paragraph":"听力原文","note":"词块：another method 另一方法；overnight 过夜；be exposed to 暴露于\n结构／听力：Another method 是方法二路标；that ... 定语从句；exposed ... 补充状态；Q35 紧接其后。"},{"en":"This would mean that a thick layer of ice would form on top, which could be discarded, leaving the sugary sap below.","zh":"这样顶部会结出一层厚冰；冰层可以被丢弃，下面的含糖树液则保留下来。","speaker":"主讲人","paragraph":"听力原文","note":"词块：a layer of ice 一层冰；discard 丢弃；sugary 含糖的\n结构／听力：Q35 removing the layer of ___ on top ↔ layer of ice ... discarded：移除的是 ice，不是下方留下的 sugary sap。"},{"en":"Again, this process could be repeated over several days, and eventually a sweet brown syrup was produced.","zh":"同样，这个过程可持续数天，最终得到棕色的甜糖浆。","speaker":"主讲人","paragraph":"听力原文","note":"词块：over several days 连续数日；eventually 最终\n结构／听力：被动结构 was produced；again 表示与第一种方法相似。"},{"en":"The First Nations people had various uses for the sap and syrup.","zh":"第一民族对树液和糖浆有多种用途。","speaker":"主讲人","paragraph":"听力原文","note":"词块：various 各种各样的；uses 用途\n结构／听力：段落标签由制作方法切换到用途；Q36 在欧洲移民部分。"},{"en":"They drank the sap fresh from the tree as a tonic, knowing that it was an important source of energy.","zh":"他们把新鲜树液当作滋补饮品直接饮用，因为他们知道它是重要的能量来源。","speaker":"主讲人","paragraph":"听力原文","note":"词块：tonic 滋补饮品；source of energy 能量来源\n结构／听力：knowing ... 现在分词解释认识或原因；题目里 energy 已给出，无须填写。"},{"en":"But for the most part, they reduced the syrup further and then cooled it so that it crystallized into sugar.","zh":"不过在大多数情况下，他们会进一步熬浓糖浆，再将其冷却，使它结晶成糖。","speaker":"主讲人","paragraph":"听力原文","note":"词块：for the most part 大体上；reduce 浓缩（熟词生义）；crystallize 结晶\n结构／听力：reduce 在烹饪语境指蒸发水分使汁液变浓；so that 引导结果/目的。"},{"en":"This was easy to carry and kept indefinitely.","zh":"这种糖便于携带，而且能长期保存。","speaker":"主讲人","paragraph":"听力原文","note":"词块：keep indefinitely 长期保存；carry 携带\n结构／听力：this 指结晶后的 maple sugar，而不是仍为液体的 syrup。"},{"en":"European settlers who arrived in Canada began to learn about the syrup from First Nations peoples and further expanded its uses.","zh":"来到加拿大的欧洲定居者开始向第一民族学习枫糖浆知识，并进一步开发其用途。","speaker":"主讲人","paragraph":"听力原文","note":"词块：settlers 定居者；expand uses 扩展用途\n结构／听力：who ... 修饰 settlers；由原住民用途转向欧洲移民用途。"},{"en":"For example, they incorporated it into medicine of different kinds.","zh":"例如，他们将它加入各种药物中。","speaker":"主讲人","paragraph":"听力原文","note":"词块：incorporate into 掺入、纳入；medicine 药物\n结构／听力：Q36 various types of ___ ↔ medicine of different kinds；答案 medicine（不可数泛指药物）。"},{"en":"They also discovered that by adding yeast to the sap, they could make a maple drink.","zh":"他们还发现，把酵母加入树液就能制成枫树液饮品。","speaker":"主讲人","paragraph":"听力原文","note":"词块：yeast 酵母；by adding ... 通过加入……\n结构／听力：by + -ing 表手段；drink 已在题干，属于干扰背景。"},{"en":"And by throwing the hot syrup into the snow, they could make a toffee-like candy.","zh":"而且把热糖浆倒进雪里，还能做出类似太妃糖的糖果。","speaker":"主讲人","paragraph":"听力原文","note":"词块：toffee-like 类似太妃糖的；candy 糖果\n结构／听力：by + -ing 再次表方法；题干 drinks and candy 是确认信息，不是答案。"},{"en":"But like the First Nations, they turned most of their sap into maple sugar.","zh":"但他们和第一民族一样，仍将大部分树液做成枫糖。","speaker":"主讲人","paragraph":"听力原文","note":"词块：turn ... into ... 转化为……\n结构／听力：but 表示从多种创新用途回到主要用途 maple sugar。"},{"en":"For most people, it was the only type of sugar they could afford, since the only alternative was the sugar imported from the Caribbean, which was made from sugarcane.","zh":"对大多数人来说，这是唯一买得起的糖，因为当时唯一的替代品是从加勒比海进口、用甘蔗制成的糖。","speaker":"主讲人","paragraph":"听力原文","note":"词块：afford 负担得起；alternative 替代品；imported 进口的\n结构／听力：since 表原因；they could afford 限定 sugar；which 解释进口糖。为 1880 价格变化做铺垫。"},{"en":"And this was very expensive.","zh":"而进口的这种糖非常昂贵。","speaker":"主讲人","paragraph":"听力原文","note":"词块：expensive 昂贵的\n结构／听力：this 指 Caribbean sugar（加勒比海进口糖），不是 maple sugar。"},{"en":"However, after eighteen eighty, the Canadian government decided to stop charging tax on Caribbean sugar, and this made it much cheaper.","zh":"然而，1880年以后，加拿大政府决定停止对加勒比海糖征税，使其大幅降价。","speaker":"主讲人","paragraph":"听力原文","note":"词块：charge tax on 对……征税；after 1880 1880年后\n结构／听力：Q37 the ___ on Caribbean sugar was removed ↔ stop charging tax；答案 tax；注意 this 指取消税的决定。"},{"en":"That meant it was no longer cost-effective to produce maple sugar.","zh":"这意味着生产枫糖不再具有成本效益。","speaker":"主讲人","paragraph":"听力原文","note":"词块：no longer 不再；cost-effective 划算的\n结构／听力：it 为形式主语（真正内容 to produce ...）；that 回指进口糖变便宜。"},{"en":"And so syrup making became the only viable industry remaining for Canadians.","zh":"因此，制作枫糖浆成为加拿大仍可持续经营的唯一相关产业。","speaker":"主讲人","paragraph":"听力原文","note":"词块：viable 可行的；remaining 剩下的\n结构／听力：and so 表结果；only viable 说明从制糖转向制糖浆。"},{"en":"And that's what we've been doing ever since.","zh":"从那时起我们便一直在做这件事。","speaker":"主讲人","paragraph":"听力原文","note":"词块：ever since 从那以后一直\n结构／听力：have been doing 现在完成进行时，表示从过去延续到现在。"},{"en":"At present, maple syrup is enjoying a boom.","zh":"目前枫糖浆产业正经历繁荣。","speaker":"主讲人","paragraph":"听力原文","note":"词块：at present 目前；boom 繁荣（熟词生义）\n结构／听力：注意先扬后抑：接下来的 However 进入 Threats。"},{"en":"In the last two decades, production has doubled in Canada.","zh":"过去二十年加拿大的枫糖浆产量翻了一番。","speaker":"主讲人","paragraph":"听力原文","note":"词块：decade 十年；double 翻倍\n结构／听力：现在完成时 has doubled；doubled = 增至原来的两倍。"},{"en":"However, serious threats remain.","zh":"然而，严重的威胁依然存在。","speaker":"主讲人","paragraph":"听力原文","note":"词块：threat 威胁；remain 仍然存在\n结构／听力：强路标：进入 Threats 的 Natural。"},{"en":"Like any agricultural product, the harvest is subject to such things as major storms or the arrival of invasive insects, both of which have happened, and these could destroy everything.","zh":"与其他农产品一样，收成会受到猛烈风暴或入侵性昆虫出现等因素的影响；这两类事件都发生过，而且可能造成毁灭性损失。","speaker":"主讲人","paragraph":"听力原文","note":"词块：be subject to 易受……影响；invasive insects 入侵性昆虫；harvest 收成\n结构／听力：Q38 destructive ___ ↔ invasive insects；填 insects（复数）；both of which 指 storms 和 insects 这两类威胁。"},{"en":"It is predicted with some certainty that in the longer term, climate change will also have an adverse effect on the sap run.","zh":"可以比较肯定地预测，从长远看，气候变化也会对树液流动产生不利影响。","speaker":"主讲人","paragraph":"听力原文","note":"词块：with some certainty 较有把握地；adverse effect 不利影响；sap run 树液流动\n结构／听力：It is predicted that ... 形式主语结构；sap run 中 run 为名词“流动期/流量”。题干已概括此处。"},{"en":"Then there are the social factors.","zh":"此外还有社会因素。","speaker":"主讲人","paragraph":"听力原文","note":"词块：social factors 社会因素\n结构／听力：强路标：由 Natural 转为 Social；为 Q39 定位。"},{"en":"Producing maple syrup is a very labor-intensive process, making it an expensive purchase.","zh":"枫糖浆生产是劳动密集型过程，因此购买它的成本较高。","speaker":"主讲人","paragraph":"听力原文","note":"词块：labor-intensive 劳动密集型的；purchase 购买的商品（熟词生义）\n结构／听力：Producing 动名词作主语；making ... 表结果；题干 expensive 已给出。"},{"en":"And of equal concern is the fact that nowadays there's a lot of competition from cheaper, artificially flavored brands.","zh":"同样令人担忧的是，如今还存在来自更廉价的人工调味品牌的大量竞争。","speaker":"主讲人","paragraph":"听力原文","note":"词块：of equal concern 同样令人担忧；competition 竞争；artificially flavored 人工调味的\n结构／听力：表语前置形成倒装：Of equal concern is the fact that...；Q39 faces considerable ___ ↔ a lot of competition，填 competition。"},{"en":"Furthermore, we're at a time when obesity is a major issue, making a product that is sixty-seven percent sugar increasingly difficult to sell.","zh":"此外，在肥胖已成为重大问题的时代，含糖量为67%的产品越来越难销售。","speaker":"主讲人","paragraph":"听力原文","note":"词块：obesity 肥胖；major issue 重大问题；increasingly 越来越\n结构／听力：when 定语从句修饰 time；making ... 结果状语；that ... 修饰 product。肥胖是社会威胁之一，但不是 Q39 空。"},{"en":"Nevertheless, there are reasons to be optimistic.","zh":"尽管如此，我们仍有理由保持乐观。","speaker":"主讲人","paragraph":"听力原文","note":"词块：nevertheless 尽管如此；optimistic 乐观的\n结构／听力：强路标：转入 Reasons for optimism；答案顺序跟随。"},{"en":"Producers are developing markets abroad.","zh":"生产商正在开拓海外市场。","speaker":"主讲人","paragraph":"听力原文","note":"词块：develop markets 开拓市场；abroad 在国外\n结构／听力：现在进行时表示持续市场拓展；对出口栏目。"},{"en":"Our syrup is currently being exported to over fifty countries.","zh":"我们的枫糖浆目前正出口至50多个国家。","speaker":"主讲人","paragraph":"听力原文","note":"词块：be exported to 出口到；over fifty 超过50\n结构／听力：现在进行时被动 is being exported；注意数字未设空。"},{"en":"Back here at home, chefs use it enthusiastically.","zh":"而在加拿大国内，厨师们也热衷使用枫糖浆。","speaker":"主讲人","paragraph":"听力原文","note":"词块：back here at home 回到本国；enthusiastically 热情地\n结构／听力：at home 这里指国内，而非家里厨房。"},{"en":"It's certainly high in calories, but it also contains proteins, minerals, and antioxidants.","zh":"它确实热量高，但也含有蛋白质、矿物质和抗氧化剂。","speaker":"主讲人","paragraph":"听力原文","note":"词块：high in calories 热量高；antioxidants 抗氧化剂\n结构／听力：certainly ... but ... 承认缺点后转折；是 Q40 healthy 的铺垫。"},{"en":"As such, it is still relatively healthy when you compare it with sugar or corn syrup.","zh":"因此，与普通糖或玉米糖浆相比，它仍相对健康。","speaker":"主讲人","paragraph":"听力原文","note":"词块：as such 因此；relatively healthy 相对健康；compare A with B 比较\n结构／听力：Q40 quite ___ compared with other sweeteners ↔ relatively healthy when compared with sugar or corn syrup。填 healthy（形容词）。"},{"en":"Canadians are proud of maple syrup and its deep roots in our history and geography.","zh":"加拿大人为枫糖浆及其在本国历史和地理中的深厚根基感到自豪。","speaker":"主讲人","paragraph":"听力原文","note":"词块：be proud of 为……自豪；deep roots 深厚根基（比喻）\n结构／听力：roots 在此不是植物根部，而是传统、历史渊源。"},{"en":"However, the primary reason for maple syrup's success around the world remains its taste.","zh":"然而，枫糖浆在世界各地获得成功的首要原因仍是它的味道。","speaker":"主讲人","paragraph":"听力原文","note":"词块：primary reason 首要原因；remain 仍然是；taste 味道\n结构／听力：主干 reason ... remains taste；对题干 main reason for popularity。"},{"en":"There's nothing quite like it.","zh":"它的风味独一无二。","speaker":"主讲人","paragraph":"听力原文","note":"词块：nothing quite like it 没有什么可与之相提并论\n结构／听力：quite 修饰 like；口语式总结。"},{"en":"That is the end of section four.","zh":"第四部分到此结束。","speaker":"主讲人","paragraph":"听力原文","note":"词块：the end of ... ……的结束\n结构／听力：考试提示，答案已出现。"},{"en":"You now have half a minute to check your answers.","zh":"现在你有半分钟检查答案。","speaker":"主讲人","paragraph":"听力原文","note":"词块：check answers 检查答案\n结构／听力：检查拼写、词性、单复数和 ONE WORD ONLY，不再根据意思随意换词。"}],"questions":[{"number":31,"question":"The production of sap needs a climate where night and day temperatures are very ___.","answer":"different","chosen":"未作答","focus":"very + 形容词；题目 night and day temperatures 对应原文 at night / during the day；hugely → very。","mistake":"推测：听到 rise sharply 后不要提前写 sharply（副词）；等结果 so they’re hugely different。","method":"看“very ___”预测形容词，听到夜降白升时把注意力锁定在因果结论。","evidence":[{"en":"In spring, the temperatures need to drop to well below zero at night, but then they need to rise sharply during the day, so they're hugely different over a twenty-four-hour period.","zh":"春季夜间温度需要降到远低于零度，白天又要急剧升高，因此24小时内昼夜温度差异很大。","speaker":"主讲人","paragraph":"听力原文","note":"词块：well below zero 远低于零度；rise sharply 急剧上升；hugely different 差异巨大\n结构／听力：drop...but rise...so different：对比—结果逻辑；Q31 的形容词答案 different 出现在 so 后。","highlight":"different"}],"wrong":true,"type":"笔记填空","instruction":"Write ONE WORD ONLY for each answer.","choices":[]},{"number":32,"question":"Folk stories claim that maple syrup was first used to cook ___.","answer":"meat","chosen":"未作答","focus":"cook ↔ boil；答案是被煮的食物 meat；不是 sap 或 syrup。","mistake":"推测：背景角色（chief, tomahawk）信息较长，不能丢失“wife + boil”这个真正的答案触发点。","method":"预判 cook 后填食品名词；听到 his wife used ... to boil 立即抓宾语。","evidence":[{"en":"His wife used this sap to boil meat, and the heat turned it into a sweet syrup, which they found delicious.","zh":"他的妻子用这树液煮肉，热量使它变成甜糖浆，他们觉得味道很好。","speaker":"主讲人","paragraph":"听力原文","note":"词块：use sth to do 用……做……；boil meat 煮肉；turn A into B 将A变成B\n结构／听力：Q32 题干 used to cook ___ ↔ used sap to boil meat，答案 meat；which 引导补充说明。","highlight":"meat"}],"wrong":true,"type":"笔记填空","instruction":"Write ONE WORD ONLY for each answer.","choices":[]},{"number":33,"question":"Sap collection in spring developed into a First Nations ___.","answer":"tradition","chosen":"未作答","focus":"Sap collection ↔ collecting the sap；developed into ↔ became；First Nations ↔ them。","mistake":"推测：本句很短且同义替换密集；如果盯着长背景会错过。","method":"预读 developed into a ___ 预测可数单数名词；听到 became a 立刻跟。","evidence":[{"en":"Collecting the sap each spring became a tradition among them.","zh":"每年春天采集树液逐渐成为他们的一项传统。","speaker":"主讲人","paragraph":"听力原文","note":"词块：collect 收集；tradition 传统\n结构／听力：动名词短语 Collecting the sap 作主语；Q33 developed into a ___ ↔ became a tradition。","highlight":"tradition"}],"wrong":true,"type":"笔记填空","instruction":"Write ONE WORD ONLY for each answer.","choices":[]},{"number":34,"question":"using hot stones to produce ___.","answer":"steam","chosen":"steem","focus":"using ↔ drop ... into；produce ↔ create；steam 正确拼写 s-t-e-a-m。","mistake":"推测：不是语义理解错误，是拼写失分。","method":"提前准备 steam /stiːm/；遇到 /iː/ 不能默认写 ee，听后检查拼写。","evidence":[{"en":"One way was to drop hot stones from a fire into the buckets to create steam.","zh":"其中一种办法是把从火里取出的热石头放进桶里，从而产生蒸汽。","speaker":"主讲人","paragraph":"听力原文","note":"词块：drop ... into 放入；steam 蒸汽\n结构／听力：One way 对应方法一；to create steam 对应 Q34 produce ___；答案 steam，注意拼写不是 steem。","highlight":"steam"}],"wrong":true,"type":"笔记填空","instruction":"Write ONE WORD ONLY for each answer.","choices":[]},{"number":35,"question":"leaving it outside at night and then removing the layer of ___ on top.","answer":"ice","chosen":"sugary","focus":"removing ↔ could be discarded；layer of ... on top 原文直接复现；ice 被移除，sugary sap 留下。","mistake":"推测：误抓最近出现的形容词 sugary；填入 layer of sugary 语法不通且对象错位。","method":"预判 layer of + 物质名词；跟“移除什么”而不是“留下什么”。","evidence":[{"en":"This would mean that a thick layer of ice would form on top, which could be discarded, leaving the sugary sap below.","zh":"这样顶部会结出一层厚冰；冰层可以被丢弃，下面的含糖树液则保留下来。","speaker":"主讲人","paragraph":"听力原文","note":"词块：a layer of ice 一层冰；discard 丢弃；sugary 含糖的\n结构／听力：Q35 removing the layer of ___ on top ↔ layer of ice ... discarded：移除的是 ice，不是下方留下的 sugary sap。","highlight":"ice"}],"wrong":true,"type":"笔记填空","instruction":"Write ONE WORD ONLY for each answer.","choices":[]},{"number":36,"question":"European settlers put the syrup in various types of ___.","answer":"medicine","chosen":"未作答","focus":"put ... in ↔ incorporated ... into；various types of ↔ of different kinds。","mistake":"推测：medicine 在此是药品/药物的不可数泛称，ONE WORD ONLY 写 medicine。","method":"看到 European settlers 与 various types of，锁定其用途举例 For example。","evidence":[{"en":"For example, they incorporated it into medicine of different kinds.","zh":"例如，他们将它加入各种药物中。","speaker":"主讲人","paragraph":"听力原文","note":"词块：incorporate into 掺入、纳入；medicine 药物\n结构／听力：Q36 various types of ___ ↔ medicine of different kinds；答案 medicine（不可数泛指药物）。","highlight":"medicine"}],"wrong":true,"type":"笔记填空","instruction":"Write ONE WORD ONLY for each answer.","choices":[]},{"number":38,"question":"Harvests may be affected by storms and destructive ___.","answer":"insects","chosen":"未作答","focus":"destructive ↔ invasive（此语境的破坏性）；storms 对应 major storms；insects 复数。","mistake":"推测：入侵性是形容词，题干空在 destructive 后，应填名词；不能写 invasive。","method":"storm 听到后准备抓并列 or 后名词；检查 -s 复数。","evidence":[{"en":"Like any agricultural product, the harvest is subject to such things as major storms or the arrival of invasive insects, both of which have happened, and these could destroy everything.","zh":"与其他农产品一样，收成会受到猛烈风暴或入侵性昆虫出现等因素的影响；这两类事件都发生过，而且可能造成毁灭性损失。","speaker":"主讲人","paragraph":"听力原文","note":"词块：be subject to 易受……影响；invasive insects 入侵性昆虫；harvest 收成\n结构／听力：Q38 destructive ___ ↔ invasive insects；填 insects（复数）；both of which 指 storms 和 insects 这两类威胁。","highlight":"insects"}],"wrong":true,"type":"笔记填空","instruction":"Write ONE WORD ONLY for each answer.","choices":[]},{"number":39,"question":"Maple syrup is expensive and faces considerable ___.","answer":"competition","chosen":"未作答","focus":"faces considerable ↔ there is a lot of；competition 是不可数名词。","mistake":"推测：昂贵的原因 labor-intensive 先出现；Q39 的答案在 of equal concern 之后，需跟随段内顺序。","method":"读 Threats—Social 标签；expensive 出现后等待下一项 threat，听 a lot of competition。","evidence":[{"en":"And of equal concern is the fact that nowadays there's a lot of competition from cheaper, artificially flavored brands.","zh":"同样令人担忧的是，如今还存在来自更廉价的人工调味品牌的大量竞争。","speaker":"主讲人","paragraph":"听力原文","note":"词块：of equal concern 同样令人担忧；competition 竞争；artificially flavored 人工调味的\n结构／听力：表语前置形成倒装：Of equal concern is the fact that...；Q39 faces considerable ___ ↔ a lot of competition，填 competition。","highlight":"competition"}],"wrong":true,"type":"笔记填空","instruction":"Write ONE WORD ONLY for each answer.","choices":[]}],"examples":[]};
